INSERT INTO `sentence_bank` VALUES (121, 'en', '我通常早上七点起床，然后喝一杯黑咖啡。', 'I usually get up at seven and have a black coffee.', 4, '2026-08-06 16:17:38');
INSERT INTO `sentence_bank` VALUES (122, 'en', '下班后，我习惯沿着河边散步半小时。', 'After work, I like walking along the river for half an hour.', 4, '2026-08-06 16:17:38');
INSERT INTO `sentence_bank` VALUES (123, 'en', '今天路上堵车，所以我比平时晚到了十分钟。', 'The traffic was heavy today, so I arrived ten minutes later than usual.', 4, '2026-08-06 16:17:38');
INSERT INTO `sentence_bank` VALUES (124, 'en', '晚餐我们简单地煮了面条，还加了两个鸡蛋。', 'We simply cooked noodles for dinner and added two eggs.', 4, '2026-08-06 16:17:38');
