INSERT INTO `sentence_bank` VALUES (128, 'en', '今晚的雨比预报的要大，记得出门带把伞。', 'The rain tonight is heavier than forecast, so remember to bring an umbrella.', 4, '2026-08-06 16:17:41');
INSERT INTO `sentence_bank` VALUES (129, 'en', '他一边听着播客，一边收拾着明天的行李。', 'He listened to a podcast while packing his luggage for tomorrow.', 4, '2026-08-06 16:17:41');
INSERT INTO `sentence_bank` VALUES (130, 'en', '冰箱里剩下的蔬菜刚好够我做一碗热汤面。', 'The leftover vegetables in the fridge are just enough for a bowl of hot noodle soup.', 4, '2026-08-06 16:17:41');
INSERT INTO `sentence_bank` VALUES (131, 'en', '我通常会在早上七点起床，然后喝一杯咖啡。', 'I usually get up at seven and then have a cup of coffee.', 4, '2026-08-06 16:17:44');
