INSERT INTO `word_bank` VALUES (59229, 'en', 'massive', '/ˈmæsɪv/', '大的，重的; 大块的，大量的; 魁伟的，结实的; 大规模的', 'adj', 'The bell is massive, weighing over 40 tons. (那口钟非常大，有40多吨重。)', 2, '2026-08-06 02:27:15', 'COCA词频', 2010);
