INSERT INTO `word_bank` VALUES (59638, 'en', 'mystery', '/ˈmɪstri/', '秘密，谜; 神秘，神秘的事物; 推理小说，推理剧; 常作 mysteries 秘技，秘诀', 'n', 'Twenty years after the event, his death remains a mystery . (事情过去二十年了，他的死仍然是个谜。)', 2, '2026-08-06 02:27:15', 'COCA词频', 2352);
