INSERT INTO `word_bank` VALUES (66325, 'en', 'erupt', '/ɪˈrʌpt/', '爆发; 喷发; 突然发生; 出疹', 'vi', 'Violence erupted after police shot a student during the demonstration. (警察向示威人群中的一名学生开枪，暴乱随之发生。)', 2, '2026-08-06 02:27:15', 'COCA词频', 5360);
INSERT INTO `word_bank` VALUES (66326, 'en', 'ethnic', '/ˈeθnɪk/', '种族的，部落的; 某文化群体的', 'adj', 'The school teaches pupils from different ethnic groups. (该校教授不同种族的小学生。)', 3, '2026-08-06 02:27:15', 'COCA词频', 1742);
INSERT INTO `word_bank` VALUES (66327, 'en', 'exceptional', '/ɪkˈsepʃənl/', '优越的; 杰出的; 例外的; 独特的', 'adj', 'A review panel concluded that there were no exceptional circumstances that would warrant a lesser penalty for him. (一个评估小组作出结论：没有什么例外情况可使他获得从轻惩罚。)', 3, '2026-08-06 02:27:15', 'COCA词频', 6086);
