INSERT INTO `word_bank` VALUES (66330, 'en', 'expenditure', '/ɪkˈspendɪtʃə(r)/', '花费，支出; 费用，经费; （尤指金钱的）支出额; （精力、时间、材料等的）耗费', 'n', 'the expenditure of time and money on your house or garden (你在房子或花园上所花费的时间和金钱)', 3, '2026-08-06 02:27:15', 'COCA词频', 5240);
INSERT INTO `word_bank` VALUES (66331, 'en', 'expertise', '/ˌekspɜ:ˈti:z/', '专门知识或技能; 专家的意见; 专家评价，鉴定', 'n', 'She was not an accountant and didn\'t have the expertise to verify all of the financial details. (她不是会计，不具有核查所有这些财政细目的专业知识。)', 3, '2026-08-06 02:27:15', 'COCA词频', 3936);
INSERT INTO `word_bank` VALUES (66332, 'en', 'extinction', '/ɪkˈstɪŋkʃn/', '熄灭; 消灭，灭绝; 废除', 'n', 'species in danger of extinction (有灭绝危险的物种)', 2, '2026-08-06 02:27:15', 'COCA词频', 7089);
INSERT INTO `word_bank` VALUES (66333, 'en', 'eyewitness', '/ˈaɪwɪtnəs/', '目击者; 目击证人', 'n', 'One eyewitness said he saw her talking to a man in a blue car. (一名目击者说他看见她在跟一个坐在蓝色汽车里的男子说话。)', 3, '2026-08-06 02:27:15', 'COCA词频', 8803);
INSERT INTO `word_bank` VALUES (66334, 'en', 'fearlessly', '/\'fɪələslɪ/', '无畏地，大胆地', 'adv', 'He used color fearlessly--they were part of his stories, and an integral part of models\' makeup, which was often key in completing the worlds McQueen envisioned. (他大胆地用着用着色彩——这是他的故事的组成部分，也是模特不可分割的组成部分，而这常是麦昆预想的世界的关键组成部分。)', 2, '2026-08-06 02:27:15', 'CET-6', NULL);
INSERT INTO `word_bank` VALUES (66335, 'en', 'fiscal', '/ˈfɪskl/', '（美）财政上的，会计的; 国库的', 'adj', 'a fiscal crisis (财政危机)', 4, '2026-08-06 02:27:15', 'COCA词频', 3669);
INSERT INTO `word_bank` VALUES (66336, 'en', 'flavor', '/\'fleɪvə/', '味; 韵味; 特点; 香料', 'n', 'When things had flavor , we knew what we were eating all the while ----and it satisfied us . (当食物有滋味的时候，我们从头到尾都知道自己吃的是什么，从中得到满足。)', 3, '2026-08-06 02:27:15', 'COCA词频', 9615);
