INSERT INTO `word_bank` VALUES (66338, 'en', 'formidable', '/ˈfɔ:mɪdəbl/', '可怕的; 令人敬畏的; 难以对付的', 'adj', 'The building is grey, formidable, not at all picturesque. (那幢建筑呈灰色，气势凛然，与漂亮沾不上边。)', 4, '2026-08-06 02:27:15', 'COCA词频', 6323);
INSERT INTO `word_bank` VALUES (66339, 'en', 'foster', '/ˈfɒstə(r)/', '培养; 抚育; 促进; 代养', 'v', 'The bishop helped foster the sense of a community embracing all classes. (主教鼓励一种包容各个阶层的社区精神。)', 3, '2026-08-06 02:27:15', 'COCA词频', 5122);
INSERT INTO `word_bank` VALUES (66340, 'en', 'frankly', '/ˈfræŋkli/', '直率地（说），坦诚地; 真诚地; 坦白地; 平心而论', 'adv', 'Frankly, I think the Internet is overrated. (坦率地说，我认为因特网被高估了。)', 4, '2026-08-06 02:27:15', 'COCA词频', 3592);
