INSERT INTO `word_bank` VALUES (66895, 'en', 'pursuit', '/pəˈsju:t/', '追赶; 工作', 'n', 'The quarterback sprinted toward the end zone with Jansen in hot pursuit (= following closely behind ) . (那名四分卫快速冲向底线区，詹森穷追不舍。)', 3, '2026-08-06 02:27:15', 'COCA词频', 3909);
