INSERT INTO `word_bank` VALUES (66908, 'en', 'linger', '/ˈlɪŋgə(r)/', '逗留，徘徊; 缓慢消失', 'vi', 'I spent a week at Kandersteg and could happily have lingered on. (我在坎德施泰格逗留了一个星期，本来还可以开开心心地多待几天。)', 3, '2026-08-06 02:27:15', 'COCA词频', 5804);
