INSERT INTO `word_bank` VALUES (67239, 'en', 'incur', '/ɪnˈkɜ:(r)/', '招致，引起; 遭受', 'vt', 'And operational downtime caused by reliability or performance problems can incur opportunity costs if customers are unable to access your system or the business is unable to do its work. (并且如果顾客不能访问你的系统或业务不能进行工作，那么由可靠性或性能问题引起的运作停工就会招致机会成本。)', 4, '2026-08-06 02:27:15', 'COCA词频', 8206);
