INSERT INTO `word_bank` VALUES (67248, 'en', 'segregation', '/ˌsegrɪˈgeɪʃn/', '分离，隔离; 种族隔离', 'n', 'The Supreme Court unanimously ruled that racial segregation in schools was unconstitutional. (最高法院一致裁定学校实施的种族隔离措施违反宪法。)', 2, '2026-08-06 02:27:15', 'COCA词频', 7467);
