INSERT INTO `word_bank` VALUES (67294, 'en', 'metropolitan', '/ˌmetrəˈpɒlɪtən/', '大都会的; 大城市的; 宗主国的; 大主教教区的', 'adj', 'a metropolitan area of South Australia (南澳大利亚的一个都市区)', 2, '2026-08-06 02:27:15', 'COCA词频', 4341);
INSERT INTO `word_bank` VALUES (67295, 'en', 'prevalence', '/\'prevələns/', '流行; 盛行; 普遍; （疾病等的）流行程度', 'n', 'However, no study on the prevalence of infertility has been conducted in this area. (但是，在这个地区不曾进行过任何关于不孕症流行情况的研究。)', 4, '2026-08-06 02:27:15', 'COCA词频', 7589);
