INSERT INTO `word_bank` VALUES (67301, 'en', 'proposition', '/ˌprɒpəˈzɪʃn/', '命题; 建议; 主张', 'n', 'He telephoned Stuart with a proposition. (他打电话给斯图尔特提了个建议。)', 4, '2026-08-06 02:27:15', 'COCA词频', 5497);
INSERT INTO `word_bank` VALUES (67302, 'en', 'dynamics', '/daɪ\'næmɪks/', '动力学、力学; （音乐中的）力度变化; 力度强弱法; 动态; 动力( dynamic的名词复数 ); 力学; 力度; 活力', 'n', 'And our goal is to find out the time, the dynamics of this problem. (我们的目的是找出时间，找出这个问题的动力学。)', 4, '2026-08-06 02:27:15', 'COCA词频', 4137);
