INSERT INTO `word_bank` VALUES (67328, 'en', 'restructure', '/ˌri:ˈstrʌktʃə(r)/', '重建; 调整; 重组', 'v', 'proposals to radically restructure Britain’s electronics industry (彻底整顿英国电子行业的提议)', 3, '2026-08-06 02:27:15', 'COCA词频', 8295);
INSERT INTO `word_bank` VALUES (67329, 'en', 'stimulus', '/ˈstɪmjələs/', '刺激物; 刺激因素; 激法物', 'n', 'Tax cuts provided the stimulus which the slow economy needed. (减税为不景气的经济带来了其所需的刺激。)', 4, '2026-08-06 02:27:15', 'COCA词频', 4573);
