INSERT INTO `word_bank` VALUES (67331, 'en', 'biochemistry', '/ˌbaɪəʊˈkemɪstri/', '生物化学; 生物化学成份', 'n', '...the effects of air pollutants on the biochemistry of plants or animals. (…大气污染物对植物或动物生化过程的影响。)', 3, '2026-08-06 02:27:15', 'COCA词频', 18688);
