INSERT INTO `word_bank` VALUES (67343, 'en', 'elevate', '/ˈelɪveɪt/', '举起; 提高; 提升; 鼓舞', 'vt', 'Language has elevated humans above the other animals. (语言使人类高于其他动物。)', 3, '2026-08-06 02:27:15', 'COCA词频', 6109);
