INSERT INTO `word_bank` VALUES (82562, 'en', 'homeland', '/ˈhəʊmlænd/', '祖国，家乡; （南非种族隔离制度下的）黑人住宅区', 'n', 'Many are planning to return to their homeland. (很多人正计划回到自己的祖国去。)', 3, '2026-08-06 02:27:16', 'COCA词频', 4188);
INSERT INTO `word_bank` VALUES (82563, 'en', 'Greece', '/ɡriːs/', '希腊', 'n', 'Alexander the Great beat every opponent between Greece and India. (亚历山大大帝打败了希腊和印度之间的每个敌手。)', 5, '2026-08-06 02:27:16', '托福', NULL);
