INSERT INTO `word_bank` VALUES (82566, 'en', 'fern', '/fɜ:n/', '<植>羊齿植物，蕨类植物', 'n', 'A ladder fern springs from a crack in the 1979 lava flows from Kilauea Volcano on the Big Island of Hawaii. (1979年，夏威夷大岛上蕨类植物生长在基拉韦厄火山所流出的阶梯形的岩浆上。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9167);
