INSERT INTO `word_bank` VALUES (82999, 'en', 'hominid', '/\'hɒmɪnɪd/', '原始人类', 'n', 'A hominid is really any extinct ape more closely related to us than the chimpanzee. (原始人类中任何一个灭绝的猿物种和我们的关系都比黑猩猩更密切。)', 4, '2026-08-06 02:27:16', '托福', NULL);
