INSERT INTO `word_bank` VALUES (83054, 'en', 'crustal', '/\'krʌstəl/', '地壳的', 'adj', 'As geologic forces pulled the crustal plate apart, new volcanoes formed in parts of the rift. (当地质作用力（试图）把地壳版块分开，版块开裂的一些地方就会形成新的火山。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (83055, 'en', 'sociologist', '/ˌsəʊsiˈɒlədʒɪst/', '社会学家', 'n', 'The findings of this sociologist are very interesting because they illustrate once again the relationship that exists between what we do in the present and the results we obtain in the future. (这个社会学家的发现是非常有趣的，因为他们在一次的说明我们现在做的和我们未来获得的结果有关系。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8694);
INSERT INTO `word_bank` VALUES (83056, 'en', 'seafloor', '/\'si,flor/', '海底', 'n', 'Sea urchins brandish their spines on the seafloor near the Channel Islands. (海胆在海峡群岛附近的海底挥舞着它们的棘突。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (83057, 'en', 'twice', '/twaɪs/', '两次; 两倍; 两遍', 'adv', 'He was questioned by police twice yesterday. (他昨天被警察审问了两次。)', 5, '2026-08-06 02:27:16', 'COCA词频', 1417);
