INSERT INTO `word_bank` VALUES (83061, 'en', 'indium', '/\'ɪndɪəm/', '[化]铟', 'n', 'Photovoltaic cells rely on amorphous or crystalline silicon, cadmium telluride, or copper indium selenide and sulfide. (光伏电池依赖于非晶态或晶态的硅，碲化镉或者硒化、硫化铜铟。)', 4, '2026-08-06 02:27:16', '托福', NULL);
