INSERT INTO `word_bank` VALUES (83066, 'en', 'footprint', '/ˈfʊtprɪnt/', '（尤指软地上的）脚印; （地板上的）脚印; <商>（建筑物或设备，尤指计算机）占用的空间; <术>（尤指来自卫星的）广播信号覆盖区', 'n', 'We followed the footprints of a deer in the snow. (我们追踪雪地里一头鹿的足迹。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8583);
