INSERT INTO `word_bank` VALUES (83072, 'en', 'surveyor', '/səˈveɪə(r)/', '测量员，勘测员; 检查员; 调查员; 鉴定人', 'n', '...the surveyor\'s maps of the Queen Alexandra Range. (…亚历山德拉皇后山脉勘测图。)', 3, '2026-08-06 02:27:16', 'COCA词频', 14725);
