INSERT INTO `word_bank` VALUES (83074, 'en', 'accumulator', '/ə\'kjuːmjʊleɪtə/', '蓄电池,积聚者', 'n', 'Here is our accumulator which has that nitrogen overpressure which upon loss of pressure in the core would automatically insert coolant into the core should there be a break. (这是我们的蓄电池，那已经氮过度增压,面临着在核心里压力的损失,那会自动的加入冷却剂到,核心去，然后就会产生一个破裂。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (83075, 'en', 'rainwater', '/ˈreɪnwɔ:tə(r)/', '雨水，软水', 'n', 'Farmers say they need less rainwater if they use fertilizer trees. (农民们说，如果它们使用肥料树，就只需要很少的雨水。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14637);
INSERT INTO `word_bank` VALUES (83077, 'en', 'realism', '/ˈri:əlɪzəm/', '（文艺的）现实主义; 现实主义的态度和行为; <哲>唯实论; 实在论', 'n', 'the realism of the horses on the carousel (旋转木马上各个木马的逼真形态)', 4, '2026-08-06 02:27:16', 'COCA词频', 7303);
INSERT INTO `word_bank` VALUES (83078, 'en', 'lava', '/ˈlɑ:və/', '熔岩; 火山岩', 'n', 'Mexico\'s Mount Colima began spewing lava and ash last night. (墨西哥科利马山昨晚开始喷发熔岩和火山灰。)', 5, '2026-08-06 02:27:16', 'COCA词频', 9269);
INSERT INTO `word_bank` VALUES (83080, 'en', 'ruminant', '/\'ruːmɪnənt/', '反刍动物(的), 沉思的', 'n&a', 'Food chemists probably can improve upon the efficiency and economics of the ruminant’s conversion of cellulose to nutrients. (反刍动物将纤维素转化为营养素的效率和经济性有可能经过食品化学家来改进。)', 3, '2026-08-06 02:27:16', '托福', NULL);
