INSERT INTO `word_bank` VALUES (83491, 'en', 'twig', '/twɪg/', '细枝，嫩枝', 'n', 'There is the bird, sitting on a twig halfway up the tree. (鸟儿在那里，栖息在树中段的一根细枝上。)', 3, '2026-08-06 02:27:16', 'COCA词频', 9731);
INSERT INTO `word_bank` VALUES (83492, 'en', 'workweek', '/\'wɜːkwiːk/', '一星期工作时间', 'n', 'a 40-hour workweek (40小时工作周)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (83493, 'en', 'clement', '/\'klem(ə)nt/', '仁慈的，温和的', 'adj', 'The planet’s history contains many less stable and clement eras than the Holocene. (地球的历史是包含了许多不如全新世稳定温和的时期的。)', 4, '2026-08-06 02:27:16', '托福', NULL);
