INSERT INTO `word_bank` VALUES (83508, 'en', 'naturalist', '/ˈnætʃrəlɪst/', '自然主义者; 博物学者; <英>买卖玩赏动物的商人; 动物标本剥制师', 'n', 'I am sometimes described as a naturalist. (有时我也被称作自然主义者。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11120);
