INSERT INTO `word_bank` VALUES (83515, 'en', 'sibling', '/ˈsɪblɪŋ/', '兄弟，姐妹', 'n', 'Most young smokers are influenced by their friends’ and older siblings’ smoking habits. (大多数年轻的吸烟者都是因为他们的朋友或者哥哥姐姐有吸烟习惯而受影响的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 4382);
INSERT INTO `word_bank` VALUES (83516, 'en', 'kestrel', '/\'kestr(ə)l/', '(一种)鹰', 'n', 'Acuteness of sight is difficult to define but if we were endowed with the eyesight of a kestrel it is estimated that we could read a newspaper at a range of 25 yards. (食肉鸟视力的敏锐度是很维定义的，但是我们可以这样给鹰的视力加以说明，如果我们具有鹰的视力，那么我们可以在25码的距离之外可以看报纸。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (83517, 'en', 'animation', '/ˌænɪˈmeɪʃn/', '生气，活泼; 动画片制作，动画片摄制', 'n', NULL, 4, '2026-08-06 02:27:16', 'COCA词频', 7706);
