INSERT INTO `word_bank` VALUES (83526, 'en', 'calcite', '/\'kælsaɪt/', '方解石', 'n', 'His team analysed mud samples from Lough Monreagh in Ireland and discovered layers of white sediment made up of calcite crystals from algae. (他的团队分析了爱尔兰洛蒙雷阿湖泥浆样本，发现了由海藻中方解石晶体构成的白色沉淀物涡旋层。)', 4, '2026-08-06 02:27:16', '托福', NULL);
