INSERT INTO `word_bank` VALUES (83552, 'en', 'properly', '/ˈprɒpəli/', '适当地; 恰当地; 正确地; 完全，非常', 'adv', 'The brakes don’t seem to be working properly. (刹车似乎不正常。)', 4, '2026-08-06 02:27:16', 'COCA词频', 2902);
INSERT INTO `word_bank` VALUES (83553, 'en', 'kohoutek', '/kə\'hu:tek/', '[天]科胡特克彗星', 'n', 'But comet kohoutek offered astronomers a unique opportunity to make a concerted attack on many of them. (科霍切克慧星为天文学家提供了 一个难得的机会，使他们能同时研究其中的许都问题。)', 3, '2026-08-06 02:27:16', '托福', NULL);
