INSERT INTO `word_bank` VALUES (83555, 'en', 'meaningful', '/ˈmi:nɪŋfl/', '意味深长的; 有意义的; 有意图的; 隽', 'adj', 'Sam and Barbara exchanged meaningful glances. (萨姆和芭芭拉交换了会意的眼神。)', 3, '2026-08-06 02:27:16', 'COCA词频', 3805);
INSERT INTO `word_bank` VALUES (83556, 'en', 'agrarian', '/əˈgreəriən/', '土地的; 农业的; 农村的; 促进农业利益的', 'adj', 'an agrarian economy (=  based on farming  ) (农业经济)', 4, '2026-08-06 02:27:16', 'COCA词频', 12621);
