INSERT INTO `word_bank` VALUES (83587, 'en', 'dispersal', '/dɪˈspɜ:sl/', '散布; 分散; 消散; 驱散', 'n', 'the role of birds in the dispersal of seeds (鸟类对传播种子的作用)', 4, '2026-08-06 02:27:16', 'COCA词频', 15914);
INSERT INTO `word_bank` VALUES (83588, 'en', 'Indiana', '/,indi\'ænə/', '印地安那州', 'n', 'I own a coffee shop in Southern Indiana. I have a room in the back where I spend most of the week. (我在南印第安纳州开了间咖啡屋，咖啡屋后面还有间屋子，我就在那度过一周的大部分时间。)', 5, '2026-08-06 02:27:16', '托福', NULL);
