INSERT INTO `word_bank` VALUES (83590, 'en', 'firn', '/\'fɪən/', '粒雪, 积雪', 'n', 'Snowslide, The Flow of snow in wind, firn, it is snow Disaster in alp. (雪崩、风吹雪及厚层积雪，是高山和严寒地区特有的一种自然灾害。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (83591, 'en', 'adulthood', '/ˈædʌlthʊd/', '成年; 成人期; “adult”的派生', 'n', 'Few people nowadays are able to maintain friendships into adulthood. (现今很少有人能够把友谊维持到成年。)', 5, '2026-08-06 02:27:16', 'COCA词频', 7917);
