INSERT INTO `word_bank` VALUES (83998, 'en', 'adaptive', '/əˈdæptɪv/', '适应的; 有适应能力的', 'adj', 'Societies need to develop highly adaptive behavioural rules for survival. (社会要生存需要建立有高度适应性的行为准则。)', 3, '2026-08-06 02:27:16', 'COCA词频', 8426);
