INSERT INTO `word_bank` VALUES (84018, 'en', 'genetically', '/dʒə\'netɪklɪ/', '创始; 遗传学; 生殖; 基因', 'adv', 'A person\'s health is often genetically predetermined. (人的体质通常是由遗传决定的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 6847);
