INSERT INTO `word_bank` VALUES (84020, 'en', 'Marseille', '/ma:\'seil/', '马赛(法国港口城市)', 'n', 'It is believed the girl lives in Marseille and was travelling with her mother to the Comoros. (确信这名小女孩住在马赛勒正准备和她妈妈一起到科摩罗斯旅行。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84021, 'en', 'diver', '/ˈdaɪvə(r)/', '潜水员; 跳水者，跳水运动员; 潜鸟; 〈俚〉潜水艇', 'n', 'Police divers have recovered the body of a sixteen year old boy. (警方潜水员已经发现了一个16岁男孩的尸体。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8399);
