INSERT INTO `word_bank` VALUES (84023, 'en', 'seabed', '/\'sibɛd/', '海底, 海床', 'n', 'The wreck was raised from the seabed in June 2000. (沉船于2000年6月从海底打捞上来。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84024, 'en', 'angiosperm', '/\'ændʒɪə(ʊ)spɜːm/', '被子植物', 'n', 'In some angiosperm the seeds are equipped with gossamer wings, like the dandelion and milkweed seeds. (有些被子植物的种子有蛛丝般的翅膀，例如蒲公英和乳草属植物的种子。)', 4, '2026-08-06 02:27:16', '托福', NULL);
