INSERT INTO `word_bank` VALUES (84035, 'en', 'chondrite', '/\'kɒndraɪt/', '球粒状陨石', 'n', 'The transitional element curves standardized by chondrite were all W type curves inclining gently to the right. (过渡元素球粒陨石标准化曲线，也均呈微向右倾斜的W形曲线。)', 3, '2026-08-06 02:27:16', '托福', NULL);
