INSERT INTO `word_bank` VALUES (84052, 'en', 'termite', '/ˈtɜ:maɪt/', '白蚁', 'n', 'A German man and woman, their faces in close-up, talked about the good and essential symbiotic nature of termite mounds, with subtitles. (一个德国男人和女人的脸部特写镜头，他们在谈论白蚁堆美好而必要的共栖性特质，带字幕。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12181);
