INSERT INTO `word_bank` VALUES (84067, 'en', 'Norway', '/\'nɔ:weɪ/', '挪威(北欧国家)', 'n', 'Sweden borders Norway and Finland. (瑞典与挪威、芬兰接壤。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84068, 'en', 'encouragement', '/ɪnˈkʌrɪdʒmənt/', '鼓励; 支持（的事物）; 激励; 促进（的事物）', 'n', 'With encouragement, Sally is starting to play with the other children. (萨莉受到了鼓励，开始和其他孩子玩起来。)', 4, '2026-08-06 02:27:16', 'COCA词频', 6281);
INSERT INTO `word_bank` VALUES (84069, 'en', 'bombard', '/bɒmˈbɑ:d/', '炮击，轰炸; <核>以高能量粒子或放射能冲击', 'vt', 'I had been in action, bombarding the Normandy coast. (我参加过轰炸诺曼底海岸的行动。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13442);
INSERT INTO `word_bank` VALUES (84070, 'en', 'backbone', '/ˈbækbəʊn/', '脊梁骨，脊椎; 分水岭; 支柱; 决心，毅力', 'n', 'You might be taking drastic measures and you\'ve got to have the backbone to do that. (你可能在采取极端措施，而且你得有骨气做它。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9970);
