INSERT INTO `word_bank` VALUES (84077, 'en', 'bacterial', '/bæk\'tɪərɪəl/', '细菌的; 细菌性', 'adj', 'Cholera is a bacterial infection. (霍乱是一种由细菌引起的感染。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8747);
