INSERT INTO `word_bank` VALUES (84609, 'en', 'synthesize', '/ˈsɪnθəsaɪz/', '综合; 人工合成; （通过化学手段或生物过程）合成; （音响）合成', 'vt', 'DDT is a pesticide that was first synthesized in 1874. (滴滴涕是最初合成于1874年的杀虫剂。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11192);
INSERT INTO `word_bank` VALUES (84610, 'en', 'magnetosphere', '/mæg\'niːtəsfɪə/', '磁气圈', 'n', 'The energy of the particles and the fields in the magnetosphere can vary by large amounts. (带电粒子的能量大小与磁气圈中的磁场的大小变化极大。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84611, 'en', 'chisel', '/ˈtʃɪzl/', '凿子，錾子; <俚>诈骗', 'n', 'He is chipping away at a block marble with a chisel. (他正在用凿子在大理石上不停地凿。)', 5, '2026-08-06 02:27:16', 'COCA词频', 18836);
