INSERT INTO `word_bank` VALUES (84613, 'en', 'informal', '/ɪnˈfɔ:ml/', '（语言） 非正式的; 口语体的; 不拘礼节的; 友好随便的', 'adj', 'The atmosphere at work is fairly informal. (工作气氛相当轻松。)', 5, '2026-08-06 02:27:16', 'COCA词频', 4579);
INSERT INTO `word_bank` VALUES (84614, 'en', 'tannin', '/\'tænɪn/', '[化]丹宁酸', 'n', 'Coffee contains tannin and antioxidants, which are good for the heart and arteries, Dr Trombetti says. (特龙贝蒂说，咖啡中含有丹宁酸和抗氧化剂，对心脏和动脉有好处。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84615, 'en', 'tourism', '/ˈtʊərɪzəm/', '旅游，观光; 旅游业', 'n', 'The country depends on tourism for much of its income. (该国的大部分收入依靠旅游业。)', 4, '2026-08-06 02:27:16', 'COCA词频', 4776);
INSERT INTO `word_bank` VALUES (84616, 'en', 'woody', '/ˈwʊdi/', '木质的; 木本的; 似木的; 多木林的', 'adj', 'Care must be taken when trimming around woody plants like shrubs and trees. (修剪像灌木和乔木这样的木本植物必须小心翼翼。)', 5, '2026-08-06 02:27:16', 'COCA词频', 15046);
