INSERT INTO `word_bank` VALUES (84653, 'en', 'strut', '/strʌt/', '炫耀; 在…上趾高气扬地走; 给…加支撑', 'vt', 'Peacocks strut in the surrounding meadow. (孔雀在周围的草地上昂首阔步。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17545);
INSERT INTO `word_bank` VALUES (84654, 'en', 'prowl', '/praʊl/', '小心翼翼地移动; 徘徊', 'vi', 'gangs of teenagers prowling the streets (在大街上鬼鬼祟祟四处游荡的少年团伙)', 5, '2026-08-06 02:27:16', 'COCA词频', 13545);
INSERT INTO `word_bank` VALUES (84982, 'en', 'individualistic', '/ˌɪndɪˌvɪdʒʊə\'lɪstɪk/', '个人主义的', 'adj', 'Most artists are very individualistic. (大多数艺术家都非常我行我素。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15379);
INSERT INTO `word_bank` VALUES (84983, 'en', 'stylistic', '/staɪˈlɪstɪk/', '文体的; 文体（论）的; 体裁上的', 'adj', 'the sculptor’s stylistic development (这位雕刻家艺术风格上的发展)', 4, '2026-08-06 02:27:16', 'COCA词频', 10879);
INSERT INTO `word_bank` VALUES (84985, 'en', 'unpleasant', '/ʌnˈpleznt/', '使人不愉快的; 不合意的; 讨厌的; 不客气的', 'adj', 'an unpleasant experience (不愉快的经历)', 3, '2026-08-06 02:27:16', 'COCA词频', 6575);
INSERT INTO `word_bank` VALUES (84986, 'en', 'softwood', '/\'sɒf(t)wʊd/', '软木材', 'n', 'It would be better to use softwood, which grows in cooler climes in sustainably managed forests. (因此，更好的办法是使用软木，软木生长在更凉爽的气候区，并且容易再生。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84987, 'en', 'arsenic', '/ˈɑ:snɪk/', '砷; 三氧化二砷，砒霜', 'n', 'His wife poisoned him with arsenic. (他妻子用砒霜把他毒死了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13126);
INSERT INTO `word_bank` VALUES (84988, 'en', 'slate', '/sleɪt/', '石板; 板岩，页岩; 行为记录; 石板色，深蓝灰色', 'n', 'There were several slates missing from the roof. (房顶有几块石板瓦掉了。)', 3, '2026-08-06 02:27:16', 'COCA词频', 10680);
INSERT INTO `word_bank` VALUES (84989, 'en', 'reptilian', '/rep\'tɪlɪən/', '爬行类动物', 'n', 'A man who switches on his emotions is more likely to go into a reptilian mode and lash out vocally or become aggressive. (情绪变化的男人更可能进入爬虫类动物模式，进行口头攻击或变得咄咄逼人。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84991, 'en', 'honeybee', '/\'hʌnɪbiː/', '蜜蜂', 'n', 'When a honeybee takes its first flight, it immediately releases its strong smelling meconium. (蜕变后的蜜蜂第一次起飞时，它会立刻将难闻的“蛹便”丢弃。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84992, 'en', 'satiric', '/sə\'tɪrɪk/', '讽刺的,挖苦的', 'adj', 'Of or relating to a genre of prose fiction that originated in Spain and depicts in realistic detail the adventures of a roguish hero, often with satiric or humorous effects. (流浪汉体裁小说的流浪汉体裁小说的，这种叙述性小说体源于西班牙，以现实主义的细节描写了一个流浪汉式主人公的历险，通常具有讽刺或幽默的效果；或关于这种小说的)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84993, 'en', 'starvation', '/stɑ:ˈveɪʃn/', '挨饿; 饥饿; 饿死; 绝食', 'n', 'people dying of starvation (快饿死的人们)', 4, '2026-08-06 02:27:16', 'COCA词频', 9815);
INSERT INTO `word_bank` VALUES (84994, 'en', 'personally', '/ˈpɜ:sənəli/', '亲自地; 就个人而言; 个别地; 私人地（与工作相对）', 'adv', 'Personally, I don’t think much of the idea. (就个人而言，我认为这个主意不怎么样。)', 4, '2026-08-06 02:27:16', 'COCA词频', 2656);
INSERT INTO `word_bank` VALUES (84995, 'en', 'spruce', '/spru:s/', '衣着整洁的; 漂亮的', 'adj', 'Trees such as spruce, pine, and oak have been planted. (像云杉、松树和橡树之类的树已经种了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17433);
INSERT INTO `word_bank` VALUES (84996, 'en', 'diffusion', '/dɪ\'fjuːʒ(ə)n/', '传播，散布', 'n', 'The invention of printing helped the diffusion of learning. (印刷术的发明有助于知识的传播。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (84997, 'en', 'whenever', '/wenˈevə(r)/', '究竟什么时候; 不论何时', 'adv', 'They were always there by you， whenever you needed them. (无论何时你需要他们，他们总是在你身边。)', 4, '2026-08-06 02:27:16', 'COCA词频', 2334);
INSERT INTO `word_bank` VALUES (84998, 'en', 'stiffen', '/ˈstɪfn/', '（使）变硬，（使）强硬; 使绷紧; 使猛烈; 使粘稠', 'vt', 'a campaign to stiffen rules against drink-driving (要求对酒后驾车严加管制的运动)', 3, '2026-08-06 02:27:16', 'COCA词频', 10006);
INSERT INTO `word_bank` VALUES (84999, 'en', 'fetus', '/\'fi:təs/', '胎，胎儿', 'n', 'Pregnant women who are heavy drinkers risk damaging the unborn fetus. (酗酒的孕妇冒有伤害胎儿的危险。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8065);
INSERT INTO `word_bank` VALUES (85000, 'en', 'feeder', '/ˈfi:də(r)/', '支流，支线; 进料器; 供给装置; 饲养员', 'n', 'The feeder fed new feed to pigs so that they laid on fresh. (饲养员用新饲料喂猪好让它们长肉。)', 3, '2026-08-06 02:27:16', 'COCA词频', 11173);
INSERT INTO `word_bank` VALUES (85001, 'en', 'reminder', '/rɪˈmaɪndə(r)/', '令人回忆起…的东西; 提醒…的东西; （告知该做某事的）通知单; 提示信', 'n', 'The last thing you\'d want is a constant reminder of a bad experience. (你最不想要的就是不断让你想起一段糟糕经历的东西。)', 5, '2026-08-06 02:27:16', 'COCA词频', 4439);
INSERT INTO `word_bank` VALUES (85002, 'en', 'foodstuff', '/ˈfu:dstʌf/', '<术>食物，食品; 粮食', 'n', 'a shortage of basic foodstuffs (基本食品短缺)', 4, '2026-08-06 02:27:16', 'COCA词频', 18487);
INSERT INTO `word_bank` VALUES (85003, 'en', 'informant', '/ɪnˈfɔ:mənt/', '提供消息的人; 告密者; 被调查者; 报告者', 'n', 'One of the witnesses was a paid informant for the FBI. (目击者之一是联邦调查局出钱雇用的线人。)', 4, '2026-08-06 02:27:16', 'COCA词频', 7220);
INSERT INTO `word_bank` VALUES (85004, 'en', 'cedar', '/ˈsi:də(r)/', '雪松; 西洋杉; 香椿; 香柏', 'n', 'The yacht is built of cedar strip planking. (这艘游艇用雪松木板材制成。)', 5, '2026-08-06 02:27:16', 'COCA词频', 9027);
INSERT INTO `word_bank` VALUES (85005, 'en', 'slab', '/slæb/', '厚板，平板，厚片; 混凝土路面', 'n', 'a concrete slab (水泥板)', 3, '2026-08-06 02:27:16', 'COCA词频', 7598);
INSERT INTO `word_bank` VALUES (85006, 'en', 'coexist', '/,kəʊɪg\'zɪst/', '共存', 'v', 'But I think both can coexist. (但是我认为两者可以共存。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85007, 'en', 'moose', '/mu:s/', '\"[动', 'n', 'So did we encounter our bear, or a moose? (那么，我们到底遇到了熊或者麋鹿吗？)', 5, '2026-08-06 02:27:16', 'COCA词频', 8147);
INSERT INTO `word_bank` VALUES (85008, 'en', 'cod', '/kɒd/', '鳕鱼; 鳕鱼肉; 袋，包; 阴囊', 'n', NULL, 4, '2026-08-06 02:27:16', 'COCA词频', 13851);
INSERT INTO `word_bank` VALUES (85009, 'en', 'frontal', '/ˈfrʌntl/', '前面的; 正面的; 前额', 'adj', 'By monitoring their brain waves, he saw a pattern of high frequency neural activity in the right frontal cortex that identified in advance who would solve a puzzle through insight and who would not. ( 通过脑电波监测，他发现这些人在解开谜语之前，其右额叶皮质会出现一种高频率的神经活动，通常在得出答案的八秒钟甚至更短的时间内发生。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11041);
INSERT INTO `word_bank` VALUES (85010, 'en', 'hexagonal', '/hek\'sæɡənəl/', '六角形的,六边的', 'adj', 'Instead it is the Desert Express that pulls in, its nine coaches in smart blue, orange and white livery with large hexagonal windows. (然而驶进车站的是沙漠快车，它的九节车厢漆成漂亮的蓝色、橙色和白色，带有六边形的车窗。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85011, 'en', 'sizable', '/\'saɪzəbl/', '相当大的，颇大的; 可观', 'adj', 'Harry inherited the house and a sizable piece of land that surrounds it. (哈里继承了那座房子和房子周围一块相当大的土地。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8762);
INSERT INTO `word_bank` VALUES (85013, 'en', 'krypton', '/\'krɪptɒn/', '[化] 氪', 'n', 'Xenon and krypton are not retained by the body so they have little effect. (氙和氪不能在人体内停留所以对人体影响很小。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85014, 'en', 'chlorophyll', '/\'klɔːrəfɪl; \'klɒ-/', '[生化]叶绿素', 'n', 'The chlorophyll in wheatgrass also helps to purify the liver. (麦草中的叶绿素同样可以帮助净化肝脏。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85015, 'en', 'xenon', '/\'zenɒn; \'ziː-/', '氙(惰性气体的一种,元素符号Xe)', 'n', 'The krypton and xenon isotope ratios in the gas samples provided a surprising result: They did not match the ratios found in the primordial cloud that spawned the solar system. (气体采样中的氪和氙同位素比值产生了一个令人吃惊的结果：这些比值跟在形成太阳系的原始云团中所发现的比值不一致。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85016, 'en', 'penicillin', '/ˌpenɪˈsɪlɪn/', '青霉素，盘尼西林', 'n', 'He reacted well to penicillin. (他对青霉素的反应良好。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17988);
INSERT INTO `word_bank` VALUES (85017, 'en', 'homestead', '/ˈhəʊmsted/', '家宅，宅地; 农场', 'n', 'He looked around, not just up the road but toward the homestead and edge of the woods. (他向四周看了看，看了看路上也看了看宅基地和树林的边缘。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13052);
INSERT INTO `word_bank` VALUES (85018, 'en', 'prestigious', '/preˈstɪdʒəs/', '受尊敬的，有声望的; <古>魔术的，欺骗的', 'adj', 'a prestigious literary award (享有盛名的文学奖)', 3, '2026-08-06 02:27:16', 'COCA词频', 6551);
INSERT INTO `word_bank` VALUES (85019, 'en', 'imitative', '/\'ɪmɪtətɪv/', '仿制的,模仿的', 'adj', 'Young people might be provoked into imitative crime by the exploits they see on TV. (年轻人可能会从电视上看到的“英勇行为”中受到启发而仿效电视主人公实施犯罪。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85020, 'en', 'incubate', '/ˈɪŋkjubeɪt/', '孵化; 培育', 'vt', 'The birds returned to their nests and continued to incubate the eggs. (那些鸟儿返巢继续孵卵。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19704);
INSERT INTO `word_bank` VALUES (85021, 'en', 'hectare', '/\'hekteə; -ɑː/', '公顷（等于1万平方米）', 'n', 'Mist rose from a nearby stand of thriving eucalyptus trees she planted after receiving title to more than a hectare of farmland. (雾气从附近生长繁茂的桉树林中升起，这些树是她在获得对一公顷多农田的所有权后栽种的。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85022, 'en', 'creator', '/kriˈeɪtə(r)/', '创造者，创作者', 'n', '...Ian Fleming, the creator of James Bond. (…伊恩·弗莱明，詹姆斯·邦德的创作者。)', 4, '2026-08-06 02:27:16', 'COCA词频', 5147);
INSERT INTO `word_bank` VALUES (85023, 'en', 'novelist', '/ˈnɒvəlɪst/', '小说家', 'n', 'The key to success as a romantic novelist is absolute belief in your story. (一个浪漫派小说家成功的关键在于对自己故事的绝对信念。)', 5, '2026-08-06 02:27:16', 'COCA词频', 6442);
INSERT INTO `word_bank` VALUES (85025, 'en', 'osprey', '/\'ɒsprɪ; -preɪ/', '白色的羽毛, 鱼鹰', 'n', NULL, 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85026, 'en', 'Scotland', '/\'skɔtlənd/', '苏格兰(英国的一部分,在不列颠北部)', 'n', 'He traveled Scotland last year. (他去年在苏格兰旅行。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85027, 'en', 'huckleberry', '/\'hʌk(ə)lb(ə)rɪ/', '越橘类', 'n', 'Groves of stunted red spruce, huckleberry, blueberry, mountain laurel, mountain holly, speckled alder, and cranberry bogs, show combinations of colors throughout the year. (发育不良云杉的小树林、黑果木、蓝莓、山月桂、山冬青，斑点桤木和种越橘的沼泽地，显示着全年各种颜色的组合。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85028, 'en', 'elk', '/elk/', '麋鹿', 'n', 'I covered the elk with a tarp and sat down near it, wrapping myself in blankets. (我用一块防水布盖住了麋鹿，然后用毯子把自己裹起来，坐在它旁边。)', 4, '2026-08-06 02:27:16', 'COCA词频', 6490);
INSERT INTO `word_bank` VALUES (85029, 'en', 'darken', '/ˈdɑ:kən/', '（使）变暗; （使）模糊', 'vt', 'The sky darkened and a few drops of rain fell. (天色变暗，落下几滴雨来。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8628);
INSERT INTO `word_bank` VALUES (85030, 'en', 'historically', '/hɪ\'stɒrɪklɪ/', '从历史角度; 在历史上; 以历史观点; 根据历史事实', 'adv', 'And historically they acted with that sense of stewardship in mind, thinking of what was appropriate for the whole system and not simply for their firm. (而且在历史上，他们也在心目中带有那种使命感，思考的是什么对这个社会是最好的，不仅仅是对自己的公司。)', 3, '2026-08-06 02:27:16', 'COCA词频', 3854);
INSERT INTO `word_bank` VALUES (85031, 'en', 'disorient', '/dɪs\'ɔ:rɪent/', '使失去方向感, 使迷惑', 'v', NULL, 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85032, 'en', 'anthocyanin', '/,ænθə(ʊ)\'saɪənɪn/', '[植]花青素, [化]花色醣苔', 'n', 'Smith says that some species, most famously maples, produce anthocyanin during autumn as a kind of antioxidant for trees. (史密斯说，一些物种，例如最有名的枫树，在秋天会产生的一种抗氧化剂的花青素。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85033, 'en', 'acidic', '/əˈsɪdɪk/', '（味）酸的', 'adj', 'Some fruit juices taste a bit acidic. (有些果汁味道略酸。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14796);
INSERT INTO `word_bank` VALUES (85034, 'en', 'fingerboard', '/\'fɪŋgəbɔːd/', '键盘', 'n', 'I\'m just doing it with a series of switches instead of a fingerboard, which we obviously don\'t have-- Okay. That\'s fine. That\'s great. (只是我用的是阀键,代替圆号上很明显没有的指板,好的,很棒)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85035, 'en', 'watercraft', '/\'wɒtəkræːft/', '船只', 'n', 'Either way it seems certain that these people were using quite sophisticated technology and watercraft to fish offshore. (不管人们用的那种方法抓鱼，似乎可以肯定，那些人使用了娴熟的技术和船只。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85036, 'en', 'buildup', '/\'bɪldʌp/', '集结, 增长', 'n', NULL, 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85037, 'en', 'varnish', '/ˈvɑ:nɪʃ/', '清漆，罩光漆; 光泽面; 假漆; 虚饰，外表', 'n', 'The varnish comes in six natural wood shades. (这种清漆有6种天然木材的色泽可选。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15780);
INSERT INTO `word_bank` VALUES (85038, 'en', 'symbiosis', '/,sɪmbɪ\'əʊsɪs; -baɪ-/', '[生]共生(现象),合作关系', 'n', '...the link between bacteria, symbiosis, and the evolution of plants and animals. (...细菌、共生和动植物进化间的联系。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85039, 'en', 'presidential', '/ˌprezɪ\'denʃl/', '\"总统[总裁，议长，董事长，校长等', 'adj', 'a presidential election (总统大选)', 5, '2026-08-06 02:27:16', 'COCA词频', 1624);
INSERT INTO `word_bank` VALUES (85040, 'en', 'Russia', '/\'rʌʃə/', '俄罗斯', 'n', 'This program is beamed at Russia. (这套节目是对俄罗斯广播的。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85041, 'en', 'organizational', '/ˌɔ:ɡənaɪ\'zeɪʃənl/', '组织的; 编制的', 'adj', 'Evelyn\'s excellent organizational skills were soon spotted by her employers. (伊夫琳出色的组织才干很快就被她的雇主发现了。)', 3, '2026-08-06 02:27:16', 'COCA词频', 4522);
INSERT INTO `word_bank` VALUES (85042, 'en', 'hypothetical', '/ˌhaɪpəˈθetɪkl/', '假设的，假定的; 有前提的; 爱猜想的; 假想', 'adj', 'The question is purely hypothetical . (这个问题完全基于假设。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8197);
INSERT INTO `word_bank` VALUES (85043, 'en', 'pastoral', '/ˈpɑ:stərəl/', '牧师的，主教的; 牧人的; 有关田园生活的; 乡村的', 'adj', 'a charming pastoral scene (迷人的田园景象)', 4, '2026-08-06 02:27:16', 'COCA词频', 7376);
INSERT INTO `word_bank` VALUES (85044, 'en', 'interglacial', '/ɪntə\'gleɪsɪəl; -ʃ(ə)l/', '间冰期的', 'adj', 'This new investigation shows temperature \'spikes\' within some of the interglacial periods over the last 340,000 years. (这项新的调查显示在过去的340,000年气温都“被钉在”间冰期内。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85045, 'en', 'detractor', '/dɪˈtræktə(r)/', '贬低者', 'n', 'The attack took many by surprise, because few had anticipated that the major detractor of the faith would be one of our own. (这一攻击使许多人非常惊奇，因为很少人料想到信仰的主要诽谤者竟是我们自己中间的一位。)', 3, '2026-08-06 02:27:16', 'COCA词频', 12811);
INSERT INTO `word_bank` VALUES (85047, 'en', 'sailfish', '/\'seɪlfɪʃ/', '旗鱼', 'n', 'A fine start to the day, and my first sailfish on a fly. (这一天的开局真不错，这也是我第一次用飞杆钓到旗鱼。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85048, 'en', 'marlin', '/\'mɑːlɪn/', '枪鱼', 'n', 'He drank a little water before he lashed the marlin to bow and stern of his skiff. (他喝了一点水，然后把马林鱼捆绑在他那条小船的头部和尾部。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85049, 'en', 'swordfish', '/ˈsɔ:dfɪʃ/', '旗鱼', 'n', '...grilled swordfish with a yoghurt dressing. (...浇上酸奶酪的烤箭鱼。)', 5, '2026-08-06 02:27:16', 'COCA词频', 17719);
