INSERT INTO `word_bank` VALUES (85483, 'en', 'daguerreotype', '/də\'gerətaɪp/', '(早期)银板照相', 'n', 'Louis-Jacques-Mandé Daguerre (November 18, 1787 � July 10, 1851) was a French artist and chemist, recognized for his invention of the daguerreotype process of photography. (路易·雅克·曼德·达盖尔（1787年11月18日——1851年7月1日）是法国美术家和化学家，因发明银版照相法而闻名。)', 4, '2026-08-06 02:27:16', '托福', NULL);
