INSERT INTO `word_bank` VALUES (85491, 'en', 'smother', '/ˈsmʌðə(r)/', '（使）窒息，（使）透不过气; 遮掩; 抑制', 'v', 'A teenage mother was accused of smothering her 3-month-old daughter. (一个少女妈妈被指控闷死自己三个月大的女儿。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11181);
INSERT INTO `word_bank` VALUES (85492, 'en', 'cavern', '/\'kæv(ə)n/', '洞穴，大山洞', 'n', 'And the Hare said to him, \'The piece of red gold that thou seekest is in the cavern that is behind thee. (小野兔告诉他说：“你所寻找的那块红色的金子就在你身后的大洞穴里。)', 3, '2026-08-06 02:27:16', '托福', NULL);
