INSERT INTO `word_bank` VALUES (85495, 'en', 'dormant', '/ˈdɔ:mənt/', '潜伏的，蛰服的，休眠的; 静止的; 资金没有利用的; 权利尚待争取的', 'adj', 'a huge dormant volcano (一座巨大的休眠火山)', 3, '2026-08-06 02:27:16', 'COCA词频', 11800);
INSERT INTO `word_bank` VALUES (85496, 'en', 'coppersmith', '/\'kɒpəsmɪθ/', '铜匠', 'n', 'The pawnshop had sold the plates of his Flora after the expiration of thirteen months. Some coppersmith had made stewpans of them. (那当铺，过了十三个月，便把他那套《植物图说》的铜版全卖了，几个铜匠拿去做了些平底锅。)', 5, '2026-08-06 02:27:16', '托福', NULL);
