INSERT INTO `word_bank` VALUES (85500, 'en', 'succulent', '/ˈsʌkjələnt/', '多汁的，多水分的，多汁性的; （植物）茎叶肥厚含水分多的，肉质的; 极有兴趣的，津津有味的，有活力的', 'adj', 'a succulent steak (美味多汁的牛排)', 5, '2026-08-06 02:27:16', 'COCA词频', 17570);
INSERT INTO `word_bank` VALUES (85501, 'en', 'micron', '/ˈmaɪkrɒn/', '微米', 'n', 'For example, if you say that something is \"a few microns across\", explain that a micron is one-millionth of a metre, and \"about one hundredth the width of a human hair\". (例如，如果您说某事物只有几微米，那么就要解释一微米是百万分之一米，大约是人头发宽度的百分之一。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17412);
INSERT INTO `word_bank` VALUES (85502, 'en', 'spout', '/spaʊt/', '喷口，喷嘴; 水柱，喷流; （鲸类的）喷水孔', 'n', 'He replaced the boiler when the last one began to spout flames. (原来的锅炉开始喷射火焰之后他便更换了一个。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16051);
INSERT INTO `word_bank` VALUES (85503, 'en', 'catastrophic', '/ˌkætə\'strɒfɪk/', '灾难的; 惨重的，悲惨结局的', 'adj', 'A tidal wave caused by the earthquake hit the coast causing catastrophic damage. (地震引发的海啸袭击了海岸，造成了灾难性的损失。)', 5, '2026-08-06 02:27:16', 'COCA词频', 7709);
