INSERT INTO `word_bank` VALUES (85513, 'en', 'perishable', '/\'perɪʃəb(ə)l/', '容易腐烂的', 'adj', 'perishable goods such as butter, milk, fruit and fish (黄油、牛奶、水果和鱼等易变质的商品)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85514, 'en', 'retract', '/rɪˈtrækt/', '撤回或撤消; 缩回; 缩进', 'vt', 'He confessed to the murder but later retracted his statement. (他承认谋杀，但后来又翻供了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14366);
