INSERT INTO `word_bank` VALUES (85533, 'en', 'sociobiology', '/,səʊsɪəʊbaɪ\'ɒlədʒɪ; ,səʊʃɪəʊ-/', '生物社会学', 'n', 'The social science middle-ground, lately known as sociobiology, claims that we learn at least some specific cultural behaviors on the basis of biological need and evolution. (社会科学的中间立场近来被称为“社会生物学”，它认为我们至少学习了一些以生物需要和进化为基础的特有的文化行为。)', 4, '2026-08-06 02:27:16', '托福', NULL);
