INSERT INTO `word_bank` VALUES (85550, 'en', 'Impressionism', '/ɪm\'preʃənɪzəm/', '印象派, 印象主义', 'n', 'Impressionism has long been one of the most popular art movements. (长期以来，印象主义一直是最具有影响力的艺术运动之一。)', 4, '2026-08-06 02:27:16', '托福', NULL);
