INSERT INTO `word_bank` VALUES (85577, 'en', 'officially', '/əˈfɪʃəli/', '官方地; 正式地; 公务上', 'adv', 'The new church was officially opened on July 5th. (新教堂于7月5日正式启用。)', 4, '2026-08-06 02:27:16', 'COCA词频', 4113);
