INSERT INTO `word_bank` VALUES (85581, 'en', 'optimal', '/ˈɒptɪməl/', '最佳的，最优的; 最理想的', 'adj', 'If you find yourself waiting to be great, yearning for the optimal time when you can “afford” to do more, then you are saying at some level, if you can’t help everyone, you help no one. (如果你发现自己等着变得伟大 渴望着最佳时间当你可以 负担得起 去做更多事情的时候 那么在一定程度上说，如果你不能帮助每个人，你对谁都没有好处。)', 4, '2026-08-06 02:27:16', 'COCA词频', 7116);
INSERT INTO `word_bank` VALUES (85582, 'en', 'tapestry', '/ˈtæpəstri/', '挂毯; 绣帷; 织锦', 'n', 'a colourful tapestry depicting a hunting scene (描绘狩猎场面的彩色壁毯)', 4, '2026-08-06 02:27:16', 'COCA词频', 10578);
INSERT INTO `word_bank` VALUES (85583, 'en', 'mechanization', '/,mekənaɪ\'zeɪʃən/', '机械化', 'n', 'We are speeding up the mechanization of our agriculture. (我们正在加快农业机械化的步伐。)', 5, '2026-08-06 02:27:16', '托福', NULL);
