INSERT INTO `word_bank` VALUES (85603, 'en', 'biotic', '/baɪ\'ɒtɪk/', '有关生命的,生物的', 'adj', 'The researchers think that their biotic games could be educational to help people learn about biology, and they also think that such a forum could serve as a place to conduct real experiments. (研究人员认为他们的生物游戏有教育意义，可以帮助人们学习生物知识，他们还认为这样的论坛可以作为进行真实实验的场地。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85604, 'en', 'firewood', '/ˈfaɪəwʊd/', '木柴; 柴火; 柴草; 荛', 'n', 'Young Geoffrey made money by chopping and selling firewood. (年轻的杰弗里靠砍柴卖柴挣钱。)', 3, '2026-08-06 02:27:16', 'COCA词频', 12813);
