INSERT INTO `word_bank` VALUES (85618, 'en', 'aragonite', '/\'ærəg(ə)naɪt/', '[矿]霰石, 文石', 'n', 'So will corals, especially those whose skeletons are composed of aragonite, a particularly unstable form of calcium carbonate. (珊瑚礁对此也受到同样的危险，对于骨骼由霰石（极不稳定的碳酸钙）构成的珊瑚来说，情况更是如此。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85619, 'en', 'unaltered', '/ʌn\'ɔːltəd; ʌn\'ɒl-/', '未被改变的', 'adj', 'The rest of the apartment had fortunately remained unaltered since that time. (从那时起公寓的其余部分就幸运地未曾改变过。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85620, 'en', 'directional', '/dəˈrekʃənl/', '方向的; 定向', 'adj', 'Unless he was equipped with a directional microphone, he was out of earshot. (除非给他配备一个定向扬声器，否则谁也听不见他。)', 5, '2026-08-06 02:27:16', 'COCA词频', 15797);
