INSERT INTO `word_bank` VALUES (85640, 'en', 'germanium', '/dʒɜː\'meɪnɪəm/', '锗', 'n', 'It s also the first germanium laser to operate at room temperature. (这同样也是第一速在室温下得到控制的锗激光。)', 4, '2026-08-06 02:27:16', '托福', NULL);
