INSERT INTO `word_bank` VALUES (85650, 'en', 'bison', '/ˈbaɪsn/', '野牛', 'n', 'Sixty acres of woods and ponds are home to camels, zebra, bison, water buffalo, ostrich and antelope. (六十英亩的森林和池塘是骆驼，斑马，野牛，水牛，鸵鸟和羚羊的家园。)', 3, '2026-08-06 02:27:16', 'COCA词频', 11088);
