INSERT INTO `word_bank` VALUES (85658, 'en', 'duct', '/dʌkt/', '管，导管; （电线，电缆等的）管道', 'n', 'Air is heated and then circulated through large ducts to all parts of the house. (空气加热后通过大管道循环输送到房子的各处。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8809);
