INSERT INTO `word_bank` VALUES (85669, 'en', 'updraft', '/\'ʌpdrɑːft/', '上升气流', 'n', 'Peak updraft strength is slightly enhanced with hodograph curvature, 29.0 m/s in B versus 26.1 in C. (山顶上升气流强度随速矢端迹曲率加大而稍有加强，在（图上）B点是每秒29米，C点是每秒26.1米。)', 4, '2026-08-06 02:27:16', '托福', NULL);
