INSERT INTO `word_bank` VALUES (85671, 'en', 'flagpole', '/\'flægpəʊl/', '旗杆', 'n', 'The new Namibian flag was hoisted up the flagpole. (纳米比亚的新国旗被升到旗杆顶上。)', 4, '2026-08-06 02:27:16', '托福', NULL);
