INSERT INTO `word_bank` VALUES (85705, 'en', 'rodeo', '/ˈrəʊdiəʊ/', '竞技表演，竞技者; （集中牛马的）圈地; （为打烙印的）驱集牛马; 牧人马术表演', 'n', NULL, 4, '2026-08-06 02:27:16', 'COCA词频', 11747);
INSERT INTO `word_bank` VALUES (85706, 'en', 'mussel', '/\'mʌsəl/', '[动]贻贝, 蚌类', 'n', 'Paul is then left to choose one box to open to retrieve the mussel. (然后让保罗选择打开其中一个箱子来获得贻贝。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (85707, 'en', 'cyan', '/\'saɪən/', '蓝绿色, 青色', 'n', 'Obviously the choice colour palette is down to you, but here I’m using a mix of green and cyan. (当然你也可以选用自己喜欢的颜色，在这里我就选择了我选择的是蓝绿色的渐变。)', 4, '2026-08-06 02:27:16', '托福', NULL);
