INSERT INTO `word_bank` VALUES (85730, 'en', 'Indus', '/\'indəs/', '印度河（印度西北部的河流）', 'n', 'One arrangement now under strain is the 1960 Indus Waters Treaty between India and Pakistan. (目前处境紧张的一项协议是1960年印度和巴基斯坦签订的印度河水域条约。)', 3, '2026-08-06 02:27:16', '托福', NULL);
