INSERT INTO `word_bank` VALUES (85982, 'en', 'pinniped', '/\'pɪnɪped/', '鳍足类的', 'adj', 'The legs were strong and ended in long feet very much like those of a modern pinniped. (它的后肢很强壮，底部有长足，非常像现在的鳍足类动物。)', 4, '2026-08-06 02:27:16', '托福', NULL);
