INSERT INTO `word_bank` VALUES (86064, 'en', 'rumen', '/\'ruːmen/', '瘤胃(反刍动物的第一胃)', 'n', 'Grazing animals do it through the celluloses generated by the microorganisms of their rumen. (食草动物利用它们瘤胃中微生物所产生的纤维素酶来水解纤维素。)', 5, '2026-08-06 02:27:16', '托福', NULL);
