INSERT INTO `word_bank` VALUES (86118, 'en', 'phosphorus', '/ˈfɒsfərəs/', '\"[化', 'n', 'Because scientists have found a bacterium that can do without phosphorus—live on arsenic instead. (因为科学家已经发现了一种细菌，可以无需磷生活而以砷代替。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14826);
