INSERT INTO `word_bank` VALUES (86207, 'en', 'birch', '/bɜ:tʃ/', '桦树，桦木; （鞭打用的）桦条', 'n', 'In Finland purists insist that only birch bark should be added. (在芬兰，纯化论者坚持说只能加白桦树皮。)', 5, '2026-08-06 02:27:16', 'COCA词频', 11802);
INSERT INTO `word_bank` VALUES (86208, 'en', 'adaptability', '/əˌdæptə\'bɪlətɪ/', '适应性; 合用性', 'n', 'You can achieve greater flexibility, adaptability, and independence when each layer is only loosely coupled to the layer above and below. (当每个层仅松散耦合到其上和其下的层时，您可以实现更强的灵活性、适应性和独立性。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18124);
