INSERT INTO `word_bank` VALUES (86210, 'en', 'prospector', '/prəˈspektə(r)/', '勘探者，探矿者', 'n', 'Although he failed as a prospector, he succeeded as a journalist. (他作为采矿者遭遇失败，但作为记者大获成功。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18798);
INSERT INTO `word_bank` VALUES (86211, 'en', 'rote', '/rəʊt/', '死记硬背; 机械的作法，生搬硬套; 涛声', 'n', 'In old-fashioned schools, much learning was by rote . (在旧式学校里，很多学习都是靠死记硬背。)', 5, '2026-08-06 02:27:16', 'COCA词频', 17696);
INSERT INTO `word_bank` VALUES (86212, 'en', 'battleship', '/ˈbætlʃɪp/', '战舰', 'n', 'A new battleship was launched from a shipyard. (一艘新战舰从船坞下水。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13751);
INSERT INTO `word_bank` VALUES (86213, 'en', 'skepticism', '/\'skeptɪsɪzəm/', '怀疑态度，怀疑论; 多疑癖', 'n', 'I know there are those who don’t believe we can do all these things. I understand the skepticism. (我知道有些人不相信我们可以完成所有这些事情，我理解他们所持的怀疑态度。)', 3, '2026-08-06 02:27:16', 'COCA词频', 7048);
