INSERT INTO `word_bank` VALUES (86220, 'en', 'outwash', '/\'aʊtwɒʃ/', '[地质]冰水沉积', 'n', 'This landslide deposit pretty much rules out the idea that the deposits farther upstream are glacial outwash. (这个滑坡沉积物大可以排除远离上游的沉积物是冰川沉积的想法。)', 4, '2026-08-06 02:27:16', '托福', NULL);
