INSERT INTO `word_bank` VALUES (86223, 'en', 'carbonic', '/kɑː\'bɒnɪk/', '(含)碳的', 'adj', 'Should the carbon dioxide mix with water underground and form carbonic acid, they say, it could leach poisonous materials from rock deep underground that could then seep out. (他们说，一旦二氧化碳与地下水融合极易形成碳酸，而这会把地下岩石中的有毒物质分解出来，从而污染我们的水资源。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (86224, 'en', 'intersect', '/ˌɪntəˈsekt/', '横断，横切，横穿', 'vt', 'So tell me about. You have done music, where do these things intersect for you? (那么，你已经做过音乐和，艺术，这些事情的交叉点在哪里呢？)', 4, '2026-08-06 02:27:16', 'COCA词频', 11198);
