INSERT INTO `word_bank` VALUES (86237, 'en', 'salinization', '/,sælɪnaɪ\'zeɪʃən/', '盐渍化', 'n', 'Rising sea levels, increasing salinization of water tables, and heat stress in association with air pollution are just some of the consequences of great concern in this part of the world. (海平面不断上升，潜水层日益盐化，以及与空气污染有关的热应力只是这个区域极令人担忧的一部分后果。)', 3, '2026-08-06 02:27:16', '托福', NULL);
