INSERT INTO `word_bank` VALUES (86619, 'en', 'rebound', '/rɪˈbaʊnd/', '弹回; 从诸如衰败或失望中恢复过来; 回荡，回响; 抢得篮板球', 'vi', 'I caught the ball on the rebound. (我接住了弹回的球。)', 3, '2026-08-06 02:27:16', 'COCA词频', 7985);
