INSERT INTO `word_bank` VALUES (86621, 'en', 'Iceland', '/\'aislənd/', '冰岛(欧洲岛名,在大西洋北部,近北极圈)', 'n', 'WHICH country will be the next Iceland? (哪个国家会成为下一个冰岛？)', 3, '2026-08-06 02:27:16', '托福', NULL);
