INSERT INTO `word_bank` VALUES (86624, 'en', 'fanciful', '/ˈfænsɪfl/', '（指人）富于幻想的; （指物）设计或装饰新颖奇特的; 奇怪的，稀奇的; 不现实', 'adj', 'a fanciful story (想象出来的故事)', 4, '2026-08-06 02:27:16', 'COCA词频', 14019);
INSERT INTO `word_bank` VALUES (86625, 'en', 'deprecate', '/\'deprɪkeɪt/', '抨击, 反对', 'v', 'He deprecated the low quality of entrants to the profession. (他抨击了行业中的滥竽充数。)', 5, '2026-08-06 02:27:16', '托福', NULL);
