INSERT INTO `word_bank` VALUES (86654, 'en', 'labellum', '/lə\'beləm/', '（兰花的） 唇瓣', 'n', 'Pollinators are often visually attracted by the shape and colours of the labellum . (传粉昆虫通常被唇瓣的形状和颜色的视觉效果所吸引。)', 5, '2026-08-06 02:27:16', '托福', NULL);
