INSERT INTO `word_bank` VALUES (86671, 'en', 'oceanographer', '/,əʊʃɪə\'nɒɡrəfə/', '海洋学者, 海洋研究者', 'n', 'The oceanographer told delegates that the problem of ocean acidification was worse in high latitudes, in the Arctic and around Antarctica, than it was nearer the equator. (这位海洋学家告诉与会代表，高纬度地区的海洋酸化问题更加严重，北极和南极周围比赤道附近糟糕得多。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (86672, 'en', 'legitimately', '/lɪ\'dʒɪtɪmətlɪ/', '正当地，合理地', 'adv', 'Methods that use this comparator legitimately depend on it to compare two files, without throwing any exceptions. (使用这个比较器的方法合理地依靠它来比较两个文件，而不抛出任何异常。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13945);
