INSERT INTO `word_bank` VALUES (86691, 'en', 'diffuses', '/dɪ\'fjuːz/', '扩散,弥漫', 'v', 'It allows nicotine to diffuse slowly and steadily into the bloodstream. (它使尼古丁缓慢、稳步地扩散到血液当中。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (86692, 'en', 'synonymous', '/sɪˈnɒnɪməs/', '同义的，类义的; 同义词的', 'adj', '\"Getting fit\" became synonymous not just with healthier living, but with a leaner, meaner body, and the ground was laid for a burgeoning gym industry. (“获得适合”成为同义词的不只是健康的生活，但一个更精简，寡情的身体，与地面是一个新兴的体育产业奠定。)', 3, '2026-08-06 02:27:16', 'COCA词频', 11045);
INSERT INTO `word_bank` VALUES (86693, 'en', 'discoloration', '/,dɪskʌlə\'reɪʃn/', '变色, 污点', 'n', 'Vitamin K is helpful in reducing discoloration and the appearance of capillaries. (维生素K能够帮助减少污点和外观毛细血管。)', 4, '2026-08-06 02:27:16', '托福', NULL);
