INSERT INTO `word_bank` VALUES (86757, 'en', 'rider', '/ˈraɪdə(r)/', '骑手，骑马的人，善于骑马的人，骑师; （精密天平上的）游（动砝）码; 附文，附加条附加条款款; 扶手', 'n', 'She is a very good and experienced rider. (她是一个有经验的优秀骑手。)', 4, '2026-08-06 02:27:16', 'COCA词频', 3857);
