INSERT INTO `word_bank` VALUES (86765, 'en', 'spurge', '/spɜːdʒ/', '[植]大戟', 'n', 'An ornamental European spurge (Euphorbia lathyris) having a latex considered to be a potential source of hydrocarbons that can be converted into fuel. (一种装饰性欧洲大戟植物（续随子大戟属） ，它所含的一种乳液据认为是一种潜在的碳氢化合物的来源，可转化成燃料。)', 4, '2026-08-06 02:27:16', '托福', NULL);
