INSERT INTO `word_bank` VALUES (86772, 'en', 'meteor', '/ˈmi:tiə(r)/', '流星; 大气现象', 'n', 'Astronomers track large meteors using radar. (天文学家使用雷达跟踪大型流星。)', 3, '2026-08-06 02:27:16', 'COCA词频', 8790);
