INSERT INTO `word_bank` VALUES (86983, 'en', 'knowledgeable', '/ˈnɒlɪdʒəbl/', '博学的，知识渊博的; 有见识的; 精明的; 博洽多闻', 'adj', 'Do you think you are more knowledgeable about life than your parents were at your age? (父母在你这个年龄时，你认为你比他们更了解生活吗？)', 4, '2026-08-06 02:27:16', 'COCA词频', 7466);
INSERT INTO `word_bank` VALUES (86985, 'en', 'geomagnetic', '/,dʒɪ(ː)əʊmæɡ\'netɪk/', '地磁的,地磁气的', 'adj', 'The resulting solar storm could cause a geomagnetic storm on Earth, knocking out electricity grids around the world for hours, days, or even months, bringing much of normal life grinding to a halt. (由其引发的太阳风暴可能会激发地磁场风暴，届时，全球电网瘫痪，时间将长达数小时，数天，甚至几个月，大量的生产生活将无法继续进行。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (86986, 'en', 'magnetize', '/\'mægnɪtaɪz/', '使磁化, 吸引', 'v', 'His dark flashing eyes seemed to magnetize her. (他那双炯炯有神的黑眼睛好像把她给迷住了。)', 4, '2026-08-06 02:27:16', '托福', NULL);
