INSERT INTO `word_bank` VALUES (86988, 'en', 'bonito', '/bə\'niːtəʊ/', '鲣', 'n', 'Get ready to savor those bonito flakes. (准备好去体味那些鲣鱼薄片。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (86990, 'en', 'hilly', '/ˈhɪli/', '多丘陵的; 多小山的; 多坡的; 峭峻的', 'adj', 'The areas where the fighting is taking place are hilly and densely wooded. (战斗发生的地区丘陵起伏，树木茂密。)', 3, '2026-08-06 02:27:16', 'COCA词频', 16217);
