INSERT INTO `word_bank` VALUES (87013, 'en', 'caput', '/\'keɪpət/', '头, 首', 'n', 'Chronic portal hypertension may lead to development of collateral circulation , which is manifested as caput medusa in the region of the umbilicus and epigastrium. (慢性门脉高压可导致侧枝循环建立，可出现脐部和上腹部局部水母头样改变。)', 4, '2026-08-06 02:27:16', '托福', NULL);
