INSERT INTO `word_bank` VALUES (87028, 'en', 'flute', '/flu:t/', '长笛，长笛吹奏者; 细长香槟杯; （柱上的）凹槽; （女服的）管状裙褶', 'n', 'The boy trilled on a flute. (男孩在长笛上吹颤音。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9018);
INSERT INTO `word_bank` VALUES (87029, 'en', 'pedagogy', '/ˈpedəgɒdʒi/', '教育学，教学法', 'n', 'I’ve learned as much about teaching from learning about marketing as I have from studying pedagogy – maybe more. (我从销售上学到的有关教育的东西和我研究教育学时候学到的一样多——可能更多。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12753);
