INSERT INTO `word_bank` VALUES (87048, 'en', 'encompass', '/ɪnˈkʌmpəs/', '围绕，包围; 包含或包括某事物; 完成', 'vt', 'His repertoire encompassed everything from Bach to Schoenberg. (他的表演曲目从巴赫到勋伯格，样样俱全。)', 4, '2026-08-06 02:27:16', 'COCA词频', 5705);
INSERT INTO `word_bank` VALUES (87049, 'en', 'metabolize', '/mɪ\'tæbəlaɪz/', '产生代谢变化', 'v', 'Diabetics cannot metabolize glucose properly. (糖尿病患者不能使葡萄糖进行恰当的新陈代谢。)', 4, '2026-08-06 02:27:16', '托福', NULL);
