INSERT INTO `word_bank` VALUES (87057, 'en', 'poorhouse', '/\'pɔːhaʊs; \'pʊəhaʊs/', '救济院', 'n', 'Transport most of us to ancient Rome and we’ll find ourselves in a poorhouse or slave barracks. (把我们中的大多数传送到古罗马去，基本只能住救济院或奴隶营房呢。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87058, 'en', 'excitation', '/,eksaɪ\'teɪʃ(ə)n/', '刺激,兴奋, 激动', 'n', NULL, 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87059, 'en', 'amniotic', '/æmnɪ\'ɒtɪk/', '[昆] 羊膜的', 'adj', 'The amniotic fluid cushioning the baby in your uterus has reached its highest level this week. (这周，子宫里起缓冲作用的羊水达到了它最高的水平。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87060, 'en', 'porpoise', '/\'pɔːpəs; \'pɒpɒɪs/', '[动]海豚, 小鲸', 'n', 'The rays are often seen gathering in groups near the surface, “flying” through the water by flapping their pectoral fins and sometimes even leaping porpoise-like into the air. (魟鱼经常会成群的聚集在水面以下，通过拍动胸鳍在水中“飞行”，有时候甚至会像海豚一样跃出海面。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87061, 'en', 'spew', '/spju:/', '呕吐; （使某事物）喷出; 涌出，射出; 渗出', 'vt', 'Factory chimneys spewed fumes out into the sky. (工厂的烟囱向空中喷吐浓烟。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10801);
INSERT INTO `word_bank` VALUES (87062, 'en', 'emanate', '/ˈeməneɪt/', '发出，散发; 放射; 起源', 'vi', 'He emanates tranquility. (他身上散发着一种恬静气质。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8861);
