INSERT INTO `word_bank` VALUES (87066, 'en', 'aggregation', '/ˌæɡrɪ\'ɡeɪʃn/', '聚集; 集成; 集结; 聚集体', 'n', 'An aggregation of fragments is the only kind of whole we now have. (这种碎片的集合体是我们现有的唯一完整无缺的方式。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17884);
INSERT INTO `word_bank` VALUES (87068, 'en', 'sleepiness', '/\'sliːpɪnɪs/', '想睡,瞌睡', 'n', 'If there is excessive daytime sleepiness and desire to nap, in spite of adequate sleep time, this might suggest a sleep disorder warranting further evaluation. (如果白天有很强的睡意，想小睡一会，虽然有充足的睡眠时间，这也许意味着睡眠障碍需要进一步评估。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87069, 'en', 'oneness', '/\'wʌnnɪs/', '单一,  统一', 'n', 'Instead of trying to disidentify from the ego, we need to embrace the ego while merging it with a sense of oneness. (不要试图从 自我作出错误的识别，我们需要在把 自我 与“ 单一性 ”的观念相合并的同时，要去包容 自我 。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87070, 'en', 'excrete', '/ɪk\'skriːt; ek-/', '排泄, 分泌', 'v', 'Your open pores excrete sweat and dirt. (你张开的毛孔排出汗液与污垢。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87071, 'en', 'infection', '/ɪnˈfekʃn/', '<医>传染，感染; 传染病，染毒物; 影响', 'n', 'The baby had an ear infection. (宝宝耳朵感染了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 2715);
