INSERT INTO `word_bank` VALUES (87082, 'en', 'meteorologist', '/ˌmi:tiəˈrɒlədʒɪst/', '气象学者', 'n', '\"This is probably one of the worst storms since 1990,\" a meteorologist in Seattle said. (西雅图气象专家表示，这也许是自1990年以来最严重的暴风雪。)', 5, '2026-08-06 02:27:16', 'COCA词频', 15767);
