INSERT INTO `word_bank` VALUES (87095, 'en', 'phoenix', '/\'fiːnɪks/', '凤凰,完人', 'n', 'And let it direct your passion with reason, that your passion may live through its own daily resurrection, and like the phoenix rise above its own ashes. (让你们的灵魂以理性引导热情的方向，这样你们的热情才会经历每日的复活，宛若凤凰从自己的灰烬中再生。)', 4, '2026-08-06 02:27:16', '托福', NULL);
