INSERT INTO `word_bank` VALUES (87203, 'en', 'gesso', '/\'dʒesəʊ/', '(雕刻、绘画用的)石膏, 石膏粉', 'n', 'Processing category:Various dry and wet materials that could be crushed, including chemical raw materials, gesso powders, hulls, grains, and plastics . (加工类别：各种可以粉碎的干湿料物，化工原料、石膏粉、皮类、粮食类、塑料类。棉花类，生物类。)', 4, '2026-08-06 02:27:16', '托福', NULL);
