INSERT INTO `word_bank` VALUES (87206, 'en', 'weft', '/weft/', '[纺]织物,信号旗', 'n', 'Usage: This detector is applied to plastic looms for stopping operation in case of broken weft and weft-out. It is composed of signal emitter, receiver and controller. (用途：本检测器用于塑料园织机在断纬、完纬时控制主机停车之功能。它由信号发射器， 信号接收器和控制器三部分组成。)', 3, '2026-08-06 02:27:16', '托福', NULL);
