INSERT INTO `word_bank` VALUES (87211, 'en', 'kennel', '/ˈkenl/', '狗窝; 养狗场', 'n', 'Once you have chosen a kennel, make a booking for your pet. (一旦您选定了养狗场，请为您的宠物预约。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16579);
INSERT INTO `word_bank` VALUES (87212, 'en', 'postmaster', '/\'pəʊs(t)mɑːstə/', '邮局局长', 'n', 'As if from far away, he hears her call to the postmaster to send for the police. (好像是从很远的地方传来的声音，他听见她在让邮政局长打电话叫警察来。)', 4, '2026-08-06 02:27:16', '托福', NULL);
