INSERT INTO `word_bank` VALUES (87229, 'en', 'deplorable', '/dɪˈplɔ:rəbl/', '糟透的，可叹的，可悲的; 应受谴责的; 破旧的', 'adj', 'The prisoners were held in deplorable conditions . (囚犯被关押在极其恶劣的环境里。)', 3, '2026-08-06 02:27:16', 'COCA词频', 18376);
INSERT INTO `word_bank` VALUES (87230, 'en', 'loneliness', '/\'ləʊnlɪnəs/', '孤独，寂寞', 'n', 'I have so many friends, but deep down, underneath, I have a fear of loneliness. (我有这么多朋友，但是内心深处我还是有一种对孤独的恐惧。)', 4, '2026-08-06 02:27:16', 'COCA词频', 7164);
