INSERT INTO `word_bank` VALUES (87232, 'en', 'puncture', '/ˈpʌŋktʃə(r)/', '刺，戳; 贬低，削弱; 揭穿', 'vt', 'She was cycling home when she had a puncture . (她骑车回家途中轮胎被扎破了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19074);
