INSERT INTO `word_bank` VALUES (87236, 'en', 'unusable', '/,ʌn\'juzəbl/', '不能用的,与众不同的', 'adj', 'Bombing had made roads and railways unusable. (轰炸使得公路和铁路都不能用。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87238, 'en', 'sepal', '/\'sep(ə)l; \'siːp(ə)l/', '萼片', 'n', 'Botany The hood-shaped sepal or corolla of some flowers. (盔状花冠（或花萼）：某些花朵盔状的花萼或花冠。)', 4, '2026-08-06 02:27:16', '托福', NULL);
