INSERT INTO `word_bank` VALUES (87240, 'en', 'glycoprotein', '/,glaɪkə(ʊ)\'prəʊtiːn/', '[化]糖蛋白类, 醣蛋白', 'n', 'Straight edge: The miracle fruit (Synsepalum dulcificum), native to West Africa, contains a glycoprotein called miraculin that binds to taste receptors on the tongue and makes sour foods taste sweet. (神秘果：一种原产于西非的水果，内含一种叫神秘果蛋白的糖蛋白。 神秘果蛋白结合在味蕾上以后，吃酸的东西也感到是甜的。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87241, 'en', 'cardiac', '/ˈkɑ:diæk/', '心脏（病）的; （胃的）贲门的', 'adj', 'cardiac surgery (心脏手术)', 4, '2026-08-06 02:27:16', 'COCA词频', 8186);
INSERT INTO `word_bank` VALUES (87242, 'en', 'glial', '/\'ɡlaɪəl/', '神经胶质的', 'adj', 'The glial tissue is where the largest percentage of brain tumors begin. (胶质组织是绝大多数脑部肿瘤的起源。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87243, 'en', 'autonomic', '/,ɔːtə\'nɒmɪk/', '自治的, 自律的', 'adj', 'Concepts such as autonomic computing will have a key role in cloud storage architectures in the future. (在未来，诸如自主计算这样的概念将在云存储架构中起到关键的作用。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87244, 'en', 'preoccupation', '/priˌɒkjuˈpeɪʃn/', '全神贯注，入神; 当务之急; 使人全神贯注的事物; 偏见，成见', 'n', 'Karouzos\'s poetry shows a profound preoccupation with the Orthodox Church. (卡鲁佐斯的诗歌表现出对东正教的深切关注。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8979);
INSERT INTO `word_bank` VALUES (87245, 'en', 'coyote', '/kaɪˈəʊti/', '郊狼（北美洲西部原野上的小狼）; 丛林狼，草原狼', 'n', NULL, 5, '2026-08-06 02:27:16', 'COCA词频', 8259);
