INSERT INTO `word_bank` VALUES (87528, 'en', 'collagen', '/ˈkɒlədʒən/', '\"[生化', 'n', 'Lemons, oranges and any other citrus fruit form collagen resulting to holding the skin cells together. It is necessary to drink fruit juices and eat fruit every day. (柠檬，橘子和任何其他柑橘类水果形成胶原蛋白，从而新生皮肤细胞组织，所以每天要多喝果汁多吃水果。)', 5, '2026-08-06 02:27:16', 'COCA词频', 15392);
