INSERT INTO `word_bank` VALUES (87582, 'en', 'riverbed', '/\'rɪvəbed/', '河床', 'n', 'Samburu man leads his cattle out of the village and across a swath of arid land toward a water well dug into a desiccated Kenyan riverbed. (一位桑布鲁男子赶着牛群走出村落，穿过一片干燥的土地，朝着在干燥河床上挖掘的一口水井进发。)', 4, '2026-08-06 02:27:16', '托福', NULL);
