INSERT INTO `word_bank` VALUES (87584, 'en', 'stipulate', '/\'stɪpjʊleɪt/', '规定, 保证', 'v', 'Laws stipulate the maximum interest rate that banks can charge. (法律对银行可以收取的最高利率作了规定。)', 4, '2026-08-06 02:27:16', '托福', NULL);
