INSERT INTO `word_bank` VALUES (87697, 'en', 'substrate', '/ˈsʌbstreɪt/', '底物; 底层; 基底; 基层', 'n', 'As chemical precursors stream onto the surface of a rolling metal or plastic substrate, they react with one another to form a network of nanoparticles. (各化学母质流向滚动中的金属或塑料基片的表面，他们互相作用，形成一层纳米级微粒网状结构。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14106);
INSERT INTO `word_bank` VALUES (87698, 'en', 'sustenance', '/ˈsʌstənəns/', '食物，营养，养料', 'n', 'Without sustenance, the animals will soon die. (没有食物，动物很快就会死亡。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14664);
