INSERT INTO `word_bank` VALUES (87704, 'en', 'loess', '/\'ləʊɪs; lɜːs/', '黄土', 'n', 'Could there have been a really large dam that caused a deep lake in both Zharu and the main valleys and is older than the loess deposits? (这儿有可能有一个真正巨大的大坝，导致扎如和主峡谷之间的深湖，并且时间比黄土沉积物还久远吗？)', 4, '2026-08-06 02:27:16', '托福', NULL);
