INSERT INTO `word_bank` VALUES (87724, 'en', 'geophysical', '/,dʒio\'fɪzɪkl/', '地球物理学的', 'adj', 'These geophysical facts affect the use of language in discussions about water, and the ways in which to think about the problems of scarcity. (这些地球物理学上的事实影响了水资源讨论中所使用的语言，并改变了思考缺水问题的方式。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (87725, 'en', 'synchronize', '/ˈsɪŋkrənaɪz/', '使同步; 使同时', 'vt', 'It was virtually impossible to synchronize our lives so as to take vacations and weekends together. (为了一起度假和过周末而要让我们的生活同步几乎是不可能的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16099);
