INSERT INTO `word_bank` VALUES (87749, 'en', 'uncritical', '/ʌn\'krɪtɪk(ə)l/', '无批判力的,不加批判的', 'adj', '...the conventional notion of women as uncritical purchasers of heavily advertised products. (...妇女是对广告轰炸宣传的商品不批判的购买者这一传统观点。)', 4, '2026-08-06 02:27:16', '托福', NULL);
