INSERT INTO `word_bank` VALUES (88035, 'en', 'enhancement', '/ɪn\'hɑ:nsmənt/', '增强; 增加; 提高; 改善', 'n', 'Progressive enhancement helps us to do that because it forces us to focus on the content and build out from there. (渐进增强能够帮助我们做到这一点，因为它让我们关注内容并且从内容开始构建。)', 4, '2026-08-06 02:27:16', 'COCA词频', 7988);
