INSERT INTO `word_bank` VALUES (88037, 'en', 'unbalance', '/ʌn\'bæl(ə)ns/', '使失衡,使精神紊乱n失衡', 'v', 'He banged against the cupboard, unbalancing a pile of books. (他砰的一声撞到橱柜上，撞翻了一堆书。)', 4, '2026-08-06 02:27:16', '托福', NULL);
