INSERT INTO `word_bank` VALUES (88040, 'en', 'hieroglyph', '/\'haɪ(ə)rəglɪf/', '象形文字, 图画文字', 'n', 'Initially the patterns I used were hieroglyph like symbols. (我所采用的图案是类似符号的象形文字。)', 4, '2026-08-06 02:27:16', '托福', NULL);
