INSERT INTO `word_bank` VALUES (88042, 'en', 'democratization', '/dɪˌmɒkrətaɪ\'zeɪʃn/', '民主化', 'n', 'These elections, he said, are “the first take and a test” of Africa’s ability to follow through on increased democratization and transparency. (他说，这些选举是非洲继续推行提高民主化和透明度进程的能力“首次得到应用和检验”。)', 5, '2026-08-06 02:27:16', 'COCA词频', 8564);
INSERT INTO `word_bank` VALUES (88043, 'en', 'peacefully', '/\'pi:sfəlɪ/', '平静地; 安宁地', 'adv', 'He died peacefully on December 10 after a short illness. (他在一场短病后于12月10日安详地离开了人世。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9277);
