INSERT INTO `word_bank` VALUES (88058, 'en', 'depiction', '/dɪ\'pɪkʃn/', '描写，叙述', 'n', 'You would think that such western imports would champion any depiction of homosexuality on television, right? (你会想，像这些西方进口会拥护电视媒体对同性恋的描写，对吧？)', 5, '2026-08-06 02:27:16', 'COCA词频', 7833);
