INSERT INTO `word_bank` VALUES (88074, 'en', 'breathtaking', '/ˈbreθteɪkɪŋ/', '非常激动人心的; 惊人的; 惊险的; 使人透不过气来的', 'adj', 'The view from my bedroom window was absolutely breathtaking. (我卧室窗外的景色美得令人窒息。)', 3, '2026-08-06 02:27:16', 'COCA词频', 10369);
