INSERT INTO `word_bank` VALUES (88076, 'en', 'loyalist', '/ˈlɔɪəlɪst/', '持现政权忠诚的人，（对统治者）效忠者，反对独立者; “loyal”的派生', 'n', 'Party loyalists responded as they always do, waving flags and carrying placards. (党的忠诚支持者们一如既往地以挥舞旗帜和高举海报作为回应。)', 3, '2026-08-06 02:27:16', 'COCA词频', 14507);
