INSERT INTO `word_bank` VALUES (88155, 'en', 'repute', '/rɪˈpju:t/', '名气; 美名; 声望; 名誉', 'n', 'Under his leadership, the U.N.\'s repute has risen immeasurably. (在他的领导下，联合国的名望得到了极大提升。)', 3, '2026-08-06 02:27:16', 'COCA词频', 19741);
INSERT INTO `word_bank` VALUES (88156, 'en', 'grizzly', '/\'grɪzlɪ/', '灰白头发的', 'adj', 'Those would be you, a human, and grizzly bear, the thing that’s approaching you alarmingly fast. (那就是你，一个人类，以及一头灰熊——它正在以惊人的速度向你奔来。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14240);
