INSERT INTO `word_bank` VALUES (88159, 'en', 'shortwave', '/\'ʃɔːt\'weɪv/', '短波', 'n', 'I use the shortwave radio to get the latest war news. (我用短波收音机收听最新战事新闻。)', 3, '2026-08-06 02:27:16', '托福', NULL);
