INSERT INTO `word_bank` VALUES (88162, 'en', 'fallout', '/ˈfɔ:laʊt/', '放射尘; （核爆炸后的）沉降物; 附带后果; 余波', 'n', 'The political fallout of the affair cost him his job. (这一事件的政治影响使他丢了工作。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9331);
