INSERT INTO `word_bank` VALUES (88207, 'en', 'primacy', '/ˈpraɪməsi/', '首位，第一位; 卓越; （英国教会）大主教的职务', 'n', 'We must give primacy to education. (我们必须以教育为本。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13185);
INSERT INTO `word_bank` VALUES (88208, 'en', 'sago', '/\'seɪgəʊ/', '西米, 西米椰子', 'n', NULL, 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88209, 'en', 'breadfruit', '/\'bredfruːt/', '面包果树', 'n', 'At the Marriott, for example, guests ramble amid breadfruit and frangipani trees and photograph one another by an enormous, amoeba-shaped swimming pool. (比如，在万豪酒店，客人们可以在面包果树和鸡蛋花树之间徜徉，在硕大的不规则形状游泳池边相互拍照。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88210, 'en', 'taro', '/\'tɑːrəʊ; \'tærəʊ/', '芋头', 'n', 'According to Deng, Japan imports taro from Chenzhou because of its high quality. (通过海港，日本也因为芋头的质量高，于是从郴州中进口。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88212, 'en', 'predetermine', '/priːdɪ\'tɜːmɪn/', '预先确定', 'v', 'What if you could predetermine the genetics of your newborn baby? (要是你能预先设定新生宝宝的基因，你会怎么办？)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88213, 'en', 'unsuspected', '/ʌnsə\'spektɪd/', '未知的, 未被怀疑的', 'adj', 'A surprising number of ailments are caused by unsuspected environmental factors. (惊人数量的慢性病是由未知的环境因素引起的。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88214, 'en', 'nitrate', '/ˈnaɪtreɪt/', '硝酸盐; 硝酸根; 硝酸盐类化肥; 硝酸酯', 'n', 'potassium nitrate (硝酸钾)', 5, '2026-08-06 02:27:16', 'COCA词频', 12068);
INSERT INTO `word_bank` VALUES (88215, 'en', 'exportation', '/,ekspɔː\'teɪʃən/', '出口', 'n', '\"The laws prohibiting such exportation must be reinstated as soon as possible, \" he said. (“关于禁止出口珍稀林木的法案必须尽快得到恢复，”他说。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88216, 'en', 'extremity', '/ɪkˈstreməti/', '端点; 尽头; 手和足; 极窘迫的境地', 'n', 'In spite of the extremity of her seclusion she was sane. (尽管完全与世隔绝，她依然神智清醒。)', 5, '2026-08-06 02:27:16', 'COCA词频', 13983);
INSERT INTO `word_bank` VALUES (88217, 'en', 'converse', '/kənˈvɜ:s/', '交谈，谈话', 'vi', 'Luke sat directly behind the pilot and conversed with him. (卢克坐在飞行员的正后方和他交谈。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11755);
INSERT INTO `word_bank` VALUES (88218, 'en', 'grounding', '/ˈgraʊndɪŋ/', '\"[电', 'n', 'The degree provides a thorough grounding in both mathematics and statistics. (这个学位提供对数学和统计学全面的基础训练。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15883);
INSERT INTO `word_bank` VALUES (88219, 'en', 'spillage', '/\'spɪlɪdʒ/', '溢出, 溢出量', 'n', NULL, 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88220, 'en', 'curiously', '/\'kjʊərɪəslɪ/', '好奇地; 奇异地; 奇怪地; 说来古怪', 'adv', 'After the second of third offence I was warned that I should be beaten next time, but I received the warning in a curiously roundabout way. (这样子一两次之后，我被警告，如果再有第三次我会挨揍的。 我以一种好奇的迂回曲则的方式接受了这个警告。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8670);
INSERT INTO `word_bank` VALUES (88221, 'en', 'redesign', '/ˌri:dɪˈzaɪn/', '重新设计', 'v', 'The hotel has recently been redesigned and redecorated. (该酒店最近刚进行了重新设计及装修。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16325);
INSERT INTO `word_bank` VALUES (88222, 'en', 'citizenry', '/ˈsɪtɪzənri/', '公民成市民（集合称）', 'n', 'He used the medium of radio when he wanted to enlist public support or reassure the citizenry. (当他想得到公众支持或恢复民信时，他使用广播作载体。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12531);
INSERT INTO `word_bank` VALUES (88223, 'en', 'wad', '/wɒd/', '填充物; 炮塞（弹塞）; 小块软物; 可观的一卷纸币，大量的钱', 'n', NULL, 4, '2026-08-06 02:27:16', 'COCA词频', 11721);
