INSERT INTO `word_bank` VALUES (88482, 'en', 'puritan', '/\'pjʊərɪt(ə)n/', '清教徒 a清教徒的', 'n', 'Bykov had forgotten that Malinin was something of a puritan. (贝科夫忘记了马利宁是个近乎清教徒式的人。)', 4, '2026-08-06 02:27:16', '托福', NULL);
