INSERT INTO `word_bank` VALUES (88484, 'en', 'ruminate', '/\'ruːmɪneɪt/', '反刍, 沉思', 'v', 'One is to see whether you have any worry triggers and to distract yourself when you begin to ruminate. (首先看看你自己是否有担忧的动机，如果当你自己出现“沉思”时，尽量分散自己的注意力。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88485, 'en', 'milkweed', '/\'mɪlkwiːd/', '乳草属植物', 'n', 'This is because their staple food, milkweed, is being used more and more as a garden ornament. (这是因为它们的主要食物乳草被越来越多的用于园林装饰。)', 3, '2026-08-06 02:27:16', '托福', NULL);
