INSERT INTO `word_bank` VALUES (88488, 'en', 'permafrost', '/\'pɜːməfrɒst/', '[地]永久冻结带', 'n', 'Yakutsk is the largest city in the world built on permafrost – soil that remains permanently frozen year round. (雅库茨克是世界上建设在永久冻土上最大的城市——土壤在全年都保持冰冻。)', 4, '2026-08-06 02:27:16', '托福', NULL);
