INSERT INTO `word_bank` VALUES (88490, 'en', 'convergence', '/kən\'vɜ:dʒəns/', '集收敛; 集合; 会聚', 'n', 'With convergence to an ideal state, you can expect the system to be in or near that ideal state. (通过收敛到一种理想状态，您可以期望系统处于或接近那一理想状态。)', 3, '2026-08-06 02:27:16', 'COCA词频', 10253);
