INSERT INTO `word_bank` VALUES (88492, 'en', 'Venice', '/ˈvɛnɪs/', '威尼斯(意大利港市)', 'n', 'They call it “the Venice of the North” and “beauty on water”. (人们把它叫做北方的威尼斯，或者水上美人。)', 4, '2026-08-06 02:27:16', '托福', NULL);
