INSERT INTO `word_bank` VALUES (88494, 'en', 'uproot', '/ˌʌpˈru:t/', '根除; 连根拔起; 把…赶出家园; 使无家可归', 'vt', 'India\'s evil caste systemremains entrenched in spite of government efforts to uproot it, a racist systemthat condemns darker skinned Indians to a life of penury and servitude. (尽管政府努力根除印度罪恶的等级制度，但其仍然根深蒂固，这是一个种族歧视制度，使得深色皮肤的印度人生活贫苦，受奴役。)', 3, '2026-08-06 02:27:16', 'COCA词频', 19811);
INSERT INTO `word_bank` VALUES (88495, 'en', 'unnatural', '/ʌnˈnætʃrəl/', '不自然的，做作的; 奇异的; 不真诚的; 违背人性的，变态的', 'adj', 'It was very cold, which seemed unnatural for late spring. (天很冷，对于晚春来说似乎不正常。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9892);
INSERT INTO `word_bank` VALUES (88497, 'en', 'nursing', '/ˈnɜ:sɪŋ/', '护理，看护; 养育', 'n', 'The elderly at the nursing home have some protections, but not much. (看护之家的老人们已经受到一些保护，但这类措施为数不多。)', 5, '2026-08-06 02:27:16', 'COCA词频', 5673);
