INSERT INTO `word_bank` VALUES (88503, 'en', 'coloration', '/ˌkʌləˈreɪʃn/', '染色，着色', 'n', 'That\'s the major reason, why I go great lengths with preparation, scanning, coloration and printing techniques. (这是重要的原因，因此，我花很长时间做准备，扫描、着色和印刷技术。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19987);
INSERT INTO `word_bank` VALUES (88504, 'en', 'butler', '/ˈbʌtlə(r)/', '男管家; 仆役长; 司膳官', 'n', 'I called for the butler to clear up the broken crockery. (我叫来男管家清理摔碎的陶瓷。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13084);
