INSERT INTO `word_bank` VALUES (88515, 'en', 'flatboat', '/\'flætbəʊt/', '(浅水)平底船', 'n', 'Huck was sitting on the gunwale of a flatboat, listlessly dangling his feet in the water and looking very melancholy. (哈克坐在一条平底船的船舷上边，两只脚没精打采地放在水里，看上去忧心忡忡。)', 4, '2026-08-06 02:27:16', '托福', NULL);
