INSERT INTO `word_bank` VALUES (88589, 'en', 'pinhole', '/\'pɪnhəʊl/', '针孔, 小孔', 'n', 'The yellow parts has small oval-shaped protrusions, each with one or two “pinhole” depressions. (黄色部分有小的椭圆形突出，每个突出又有一到二个“针孔”状凹陷。)', 4, '2026-08-06 02:27:16', '托福', NULL);
