INSERT INTO `word_bank` VALUES (88592, 'en', 'wintertime', '/\'wɪntətaɪm/', '冬, 冬季', 'n', 'This photo of the towers was taken during wintertime. (这些钙华塔的照片是在冬季拍摄的。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88595, 'en', 'cobble', '/ˈkɒbl/', '粗劣地制作; 修（鞋）; 匆匆制作; 胡乱拼凑', 'vt', 'And such urban architecture - from the simplicity of small, cobble-and-whitewash towns to the 17th-century glories of Cartagena and Popayán. (如此的城市建筑，有简朴的铺着鹅卵石道路和白色房屋的小镇，也有遗留着17世纪荣光的喀他赫纳和博帕雍。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18900);
INSERT INTO `word_bank` VALUES (88596, 'en', 'literate', '/ˈlɪtərət/', '有读写能力的; 有文化修养的', 'adj', 'Over one-quarter of the adult population are not fully literate. (四分之一以上的成年人是半文盲。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12413);
