INSERT INTO `word_bank` VALUES (88609, 'en', 'stubble', '/ˈstʌbl/', '作物收割后遗留在地里的残茎，茬子; 短而硬的胡茬子; 短粗硬毛; 楂', 'n', 'The stubble was burning in the fields. (残株在田地里燃烧着。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14899);
