INSERT INTO `word_bank` VALUES (88636, 'en', 'vibrato', '/vɪ\'brɑːtəʊ/', '颤音, 振动', 'n', 'So at first glance, the idea of a seasonal flamenco Christmas performance seems as wobbly as a cantaora\'s vibrato. (所以初看上去，弗拉门戈舞作为圣诞季节的表演与女歌星Cantaora 的颤音一样令人心颤而略带伤感。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (88637, 'en', 'sparrow', '/ˈspærəʊ/', '麻雀; 〈美〉个子小的人', 'n', 'The myrtle, dove, sparrow, and swan are sacred to her. (桃金娘，鸽子，麻雀和天鹅是她的圣物。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14639);
