INSERT INTO `word_bank` VALUES (88851, 'en', 'stratification', '/ˌstrætɪfɪˈkeɪʃn/', '层理; 成层; 层化; 分层', 'n', 'The Indian caste system is an example of social stratification . (印度的种姓制度是社会阶层化的一个例子。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19242);
INSERT INTO `word_bank` VALUES (88852, 'en', 'microcosm', '/ˈmaɪkrəʊkɒzəm/', '微观世界; 小宇宙; 缩影; 小规模地', 'n', 'In each one of these places you will find a microcosm of molecules which directly impact the look, smell, touch, and sound of everything that you see. (在每一个这样的地方，你都可以发现分子的微观世界，它们会直接影响你所见物质的外观、气味、触感和声音。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14950);
