INSERT INTO `word_bank` VALUES (88997, 'en', 'rename', '/ˌri:ˈneɪm/', '给…重新取名，改名', 'vt', 'Tel Aviv\'s Kings Square was renamed Yitzhak Rabin Square. (特拉维夫的国王广场更名为伊扎克·拉宾广场。)', 3, '2026-08-06 02:27:16', 'COCA词频', 9451);
