INSERT INTO `word_bank` VALUES (89009, 'en', 'girder', '/\'gɜːdə/', '梁', 'n', 'Listen, when you start to feel weak, just tell yourself, ‘I’m as strong as a girder’ . (听着，当你开始觉得虚弱的时候，就对自己说：‘我像 钢梁 一样强壮’。)', 4, '2026-08-06 02:27:16', '托福', NULL);
