INSERT INTO `word_bank` VALUES (89079, 'en', 'optometrist', '/ɒp\'tɒmɪtrɪst/', '验光师, 视力测定者', 'n', 'One evaluation has shown that 70% of the people who received the new glasses corrected their own vision at least as well, if not better, than a trained optometrist. (评价表明，在得到新型眼镜的人中，有70％的人最起码与一位训练有素的验光配镜师一样很好地矫正了其视力。)', 4, '2026-08-06 02:27:16', '托福', NULL);
