INSERT INTO `word_bank` VALUES (89089, 'en', 'uncontrollably', '/,ʌnkən\'trəuləbli/', '无法管束的, 控制不住的', 'adj', 'This means your blood does not clot and you will bleed uncontrollably. (这意味着你的血液不会凝固，你会控制不住地出血。)', 4, '2026-08-06 02:27:16', '托福', NULL);
