INSERT INTO `word_bank` VALUES (89092, 'en', 'multidirectional', '/,mʌltɪdɪ\'rekʃ(ə)n(ə)l; -daɪ-/', '多方向的', 'adj', 'A new nonlinear weighted average multidirectional morphological filtering algorithm is proposed, which is used in suppressing speckle noise. (提出了一种新的用于散斑噪声抑制的非线性加权均值多方向形态滤波算法。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89093, 'en', 'curio', '/\'kjʊərɪəʊ/', '古董, 古玩', 'n', 'Red and blue spectacles, it was imagined, would be routinely employed to watch a film. Flat projection would be a historical curio. (当时人们认为那种红蓝3D眼镜将是未来观影必备物品，平板投射技术将成为历史古董。)', 4, '2026-08-06 02:27:16', '托福', NULL);
