INSERT INTO `word_bank` VALUES (89095, 'en', 'speck', '/spek/', '污点; 微粒', 'n', 'He has even cut himself shaving. There is a speck of blood by his ear. (他甚至在刮脸时划伤了自己。他耳边有一点血迹。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10706);
INSERT INTO `word_bank` VALUES (89096, 'en', 'encircle', '/ɪnˈsɜ:kl/', '包围; 围绕', 'vt', 'The island was encircled by a dusty road. (那座岛屿为一条尘土飞扬的公路所环绕。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10822);
