INSERT INTO `word_bank` VALUES (89100, 'en', 'mycology', '/maɪ\'kɒlədʒɪ/', '[植]真菌学', 'n', 'It is active in under- and postgraduate training in the fields of botany, mycology , and plant physiology. (该所积极参于植物学，真菌学，和植物生理学领域的本科生和研究生训练。)', 3, '2026-08-06 02:27:16', '托福', NULL);
