INSERT INTO `word_bank` VALUES (89108, 'en', 'varve', '/vɑːv/', '[地质]纹泥', 'n', 'Recently the study of maar lake and varve chronology is becoming a new field for palaeoclimate research. (火山活动是影响全球变化的重要因素之一，玛珥湖和纹泥年代学是近年来古气候研究的新领域。)', 5, '2026-08-06 02:27:16', '托福', NULL);
