INSERT INTO `word_bank` VALUES (89124, 'en', 'stratagem', '/\'strætədʒəm/', '战略, 计谋', 'n', 'Trade discounts may be used as a competitive stratagem to secure customer loyalty. (商业折扣可以用作保持顾客忠诚度的一种竞争策略。)', 4, '2026-08-06 02:27:16', '托福', NULL);
