INSERT INTO `word_bank` VALUES (89147, 'en', 'modestly', '/\'mɒdɪstlɪ/', '谦虚地，审慎地; 适度地', 'adv', '‘And I think you’ve got to have an awful lot of talent to then go and do what the Beatles did – he says modestly. (我想你一定得有相当出众的才华才能达到甲壳虫所达到的高度——他（书作者）说的很谨慎。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11765);
