INSERT INTO `word_bank` VALUES (89150, 'en', 'juggle', '/ˈdʒʌgl/', '用…玩杂耍，边抛边接; 歪曲，篡改; 欺骗; 失去平衡', 'vt', 'Soon she was juggling five eggs. (很快她就在抛接5个鸡蛋了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9809);
