INSERT INTO `word_bank` VALUES (89172, 'en', 'unnoticeable', '/ʌn\'nəʊtɪsəb(ə)l/', '不引人注意的(', 'adj', 'They might kill people slowly in a way that\'s unnoticeable, taking effect over perhaps 10 - 30 years by accelerating degenerative diseases. (它们可能用不引人注意的方式缓慢地杀害人民，促进退化性疾病也许在10-30年生效。)', 4, '2026-08-06 02:27:16', '托福', NULL);
