INSERT INTO `word_bank` VALUES (89230, 'en', 'stele', '/stiːl; \'stiːlɪ/', '石碑,  匾额', 'n', 'We do have a victory hymn, a victory hymn that\'s inscribed on a stele that\'s a slab of stone--which was erected in the year 1204 BCE. (我们确实有胜利颂歌，刻在石碑上的胜利颂歌,那是一块石板，立于公元前1204年。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89231, 'en', 'chronology', '/krəˈnɒlədʒi/', '年代学; 年表，（按时间排列的）大事记', 'n', 'The book includes a chronology of his life and works. (本书附有他的生平和著作年表。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13070);
INSERT INTO `word_bank` VALUES (89233, 'en', 'eminence', '/\'emɪnəns/', '出众, 显赫', 'n', 'Many of the pilots were to achieve eminence in the aeronautical world. (其中的很多飞行员后来在航空界都取得了显赫的声名。)', 3, '2026-08-06 02:27:16', '托福', NULL);
