INSERT INTO `word_bank` VALUES (89236, 'en', 'prearrange', '/priːə\'reɪndʒ/', '预先安排', 'v', 'When you prearrange your funeral, you can pick your own flowers and music. (当你预先准备自己的葬礼时，你就能够选择自己喜欢的鲜花和音乐。)', 4, '2026-08-06 02:27:16', '托福', NULL);
