INSERT INTO `word_bank` VALUES (89247, 'en', 'astrological', '/,æstrə\'lɔdʒik,-kəl/', '占星的, 占星术的', 'adj', 'So, the problem with astrological predictions is not that they\'re wrong. (占星预测的问题并不在于它们是错误的。)', 5, '2026-08-06 02:27:16', '托福', NULL);
