INSERT INTO `word_bank` VALUES (89252, 'en', 'schoolroom', '/\'skuːlruːm; -rʊm/', '教室', 'n', 'They seemed like so many little flags dotted about the schoolroom. (这些卡片就像无数面小旗点缀着教室。)', 4, '2026-08-06 02:27:16', '托福', NULL);
