INSERT INTO `word_bank` VALUES (89257, 'en', 'interject', '/ˌɪntəˈdʒekt/', '（突然）插入，插话; 打断', 'vt', '‘That’s absolute rubbish!’ he interjected. (“那全是废话！”他突然插话道。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14979);
