INSERT INTO `word_bank` VALUES (89285, 'en', 'academically', '/ˌækə\'demɪklɪ/', '从学术观点; 关于学院或大学; 关于学会或协会; 以学者风度', 'adv', 'Challenge yourself academically, but give yourself plenty of time for fun as well. (学业上要努力，但也要给自己充足的娱乐时间。)', 3, '2026-08-06 02:27:16', 'COCA词频', 9527);
