INSERT INTO `word_bank` VALUES (89290, 'en', 'embroider', '/ɪmˈbrɔɪdə(r)/', '刺绣; 在…上绣花; 渲染', 'vt', 'a richly embroidered jacket (刺绣华美的夹克衫)', 4, '2026-08-06 02:27:16', 'COCA词频', 14251);
