INSERT INTO `word_bank` VALUES (89293, 'en', 'gentlemanly', '/\'dʒent(ə)lmənlɪ/', '绅士派头的', 'adj', 'He was respected by all who knew him for his kind and gentlemanly consideration. (他为人谦和而且有绅士风度，认识他的人都很尊重他。)', 3, '2026-08-06 02:27:16', '托福', NULL);
