INSERT INTO `word_bank` VALUES (89489, 'en', 'gouache', '/guː\'ɑːʃ; gwɑːʃ/', '树胶水彩画', 'n', 'Her preferred medium is oil, but she also enjoys acrylic, gouache , and pen and wash. (她主要是画油画，但对丙烯，水粉画，钢笔和水彩画也很感兴趣。)', 4, '2026-08-06 02:27:16', '托福', NULL);
