INSERT INTO `word_bank` VALUES (89496, 'en', 'scour', '/ˈskaʊə(r)/', '冲刷; 擦亮; 四处搜索; （用泻药）泻', 'v', 'Rescue crews had scoured an area of 30 square miles. (救援人员已经搜遍了30平方英里的范围。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9727);
INSERT INTO `word_bank` VALUES (89497, 'en', 'philology', '/fɪ\'lɒlədʒɪ/', '语言学, 文献学', 'n', 'I don\'t know the philology side, I don\'t know what disables to metaphysical questions. (我不知道者从语言学上来说对不对，我也不懂从形而上学角度看,有什么问题。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89498, 'en', 'unobservable', '/ʌnəb\'zɜːvəb(ə)l/', '不可见的', 'adj', 'It basically means that you have a theory about the unobservable psychological states that are governing — or causing — other people\'s behaviors. (这基本上意味着你能推测到，那些支配或引起他人行为的不可观察的心理状态。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89500, 'en', 'balsam', '/\'bɔːlsəm; \'bɒl-/', '香液', 'n', 'Soon a dark wall of trees—red spruce, balsam fir, beech, hemlock—surrounds you, and there\'s a sudden stony persistence. (很快你会被一堵厚厚的树墙包围——红云杉、香脂冷杉、山毛榉和铁杉，这会持续一段时间。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89501, 'en', 'weightily', '/\'weɪtɪlɪ/', '沉重地, 重要地', 'adv', NULL, 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89502, 'en', 'zoology', '/zuː\'ɒlədʒɪ; zəʊ-/', '动物学, 生态', 'n', 'The scholarship money she won helped her attend Cornell University, where she majored in zoology. (她赢得的奖学金帮助她上康奈尔大学，在那里他主修动物学。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89503, 'en', 'horseback', '/ˈhɔ:sbæk/', '马背; 隆起的条状地带（山脊）', 'n', 'In remote mountain areas, voters arrived on horseback. (在偏远山区，选民们是骑着马来的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9531);
INSERT INTO `word_bank` VALUES (89505, 'en', 'nonessential', '/,nɒnɪ\'senʃəl/', '非本质的', 'adj', 'The crisis has led to the closure of a number of nonessential government services. (这场危机已导致了一些可有可无政府服务设施的关闭。)', 4, '2026-08-06 02:27:16', '托福', NULL);
