INSERT INTO `word_bank` VALUES (89507, 'en', 'pearly', '/ˈpɜ:li/', '珍珠似的，用珍珠装饰的', 'adj', 'pearly white teeth (珍珠般洁白的牙齿)', 4, '2026-08-06 02:27:16', 'COCA词频', 19400);
