INSERT INTO `word_bank` VALUES (89564, 'en', 'moralistic', '/mɒrə\'lɪstɪk/', '狭隘道德观的, 说教的', 'adj', 'It’s difficult to talk to teenagers about drugs without sounding too moralistic. (跟青少年谈论毒品，又不能有太重的说教味道，这是很难的。)', 3, '2026-08-06 02:27:16', '托福', NULL);
