INSERT INTO `word_bank` VALUES (89600, 'en', 'germination', '/,dʒɝmə\'neʃən/', '萌芽, 发生', 'n', 'In this way, postmodernism might be seen as the delayed germination of an older seed, planted by artists like Marcel Duchamp, during modernism’s high noon of the 1920s and 1930s. (按这种理解，后现代主义可被看成一粒过往的种子延迟了的萌芽，这粒种子由马塞尔•杜尚等艺术家种在20世纪二三十年代现代主义的繁盛时期。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89601, 'en', 'unseen', '/ˌʌnˈsi:n/', '看不见的; 未看见的; 未事先过目的; 即席的', 'adj', 'Raj crept out of the house unseen. (拉杰悄悄地溜出了房子。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8164);
INSERT INTO `word_bank` VALUES (89602, 'en', 'cognition', '/kɒg\'nɪʃ(ə)n/', '认识', 'n', 'the regions of the brain that are responsible for memory and cognition (大脑主管记忆与认知的区域)', 5, '2026-08-06 02:27:16', '托福', NULL);
