INSERT INTO `word_bank` VALUES (89632, 'en', 'nonliving', '/nɒn\'lɪvɪŋ/', '无生命的, 非活体的', 'adj', 'In 1860 Louis Pasteur performed experiments that eventually disproved “spontaneous generation, ” the idea that life continually arose from nonliving things. (1860年，路易斯巴斯德做了个实验，最终反驳了“自然发生说”，这一说认为生命源源不断于无生命的物体。)', 4, '2026-08-06 02:27:16', '托福', NULL);
