INSERT INTO `word_bank` VALUES (89635, 'en', 'wok', '/wɒk/', '锅，炒菜锅', 'n', 'Then Ky-Phuong Luong, the T.A., stirred a wok full of vegetables and soy-marinated crickets, and Dunkel passed a plate of fritters with yellowish wax worms protruding from their centers. (然后名叫罗芳婉的班主任老师炒了锅菜满是蔬菜和过了酱的蟋蟀，接着邓克尔端上一盘油炸面团，内馅儿是蜡蠕虫，一些淡黄的的蠕虫凸出面团。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19761);
INSERT INTO `word_bank` VALUES (89636, 'en', 'lone', '/ləʊn/', '孤单的; 孤独的; 人迹稀少的; 孤寂的', 'adj', 'A lone figure was standing at the bus stop. (公交车站上站着一个孤单的身影。)', 5, '2026-08-06 02:27:16', 'COCA词频', 5446);
