INSERT INTO `word_bank` VALUES (89664, 'en', 'cementation', '/,siːmen\'teɪʃ(ə)n/', '粘固', 'n', 'Deep caries based by the glass ions cementation agent, could significantly reduce composite resin pulp stimulation to protect pulp, and better effect. (深龋经玻璃离子粘固剂垫底后，能明显减轻复合树脂对牙髓的刺激作用，从而护髓效果更佳。)', 5, '2026-08-06 02:27:16', '托福', NULL);
