INSERT INTO `word_bank` VALUES (89822, 'en', 'yesteryear', '/\'jestəjɪə; -jɜː/', '去年 ad过去不久的岁月', 'n', 'The modern-day sex symbol has now taken the place of the old-fashioned hero of yesteryear. (当今的性感偶像已经取代了往昔过时的英雄形象。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89823, 'en', 'lore', '/lɔ:(r)/', '（专门的）知识; 学问; 口头传说', 'n', 'According to local lore, a ghost still haunts the castle. (根据当地人的传说，城堡里至今仍然闹鬼。)', 3, '2026-08-06 02:27:16', 'COCA词频', 10941);
INSERT INTO `word_bank` VALUES (89824, 'en', 'mortar', '/ˈmɔ:tə(r)/', '迫击炮; 砂浆; 房产; 研钵', 'n', 'A cameraman was killed when his vehicle came under mortar fire . (一名摄影师因所乘坐的汽车遭到迫击炮袭击而丧生。)', 5, '2026-08-06 02:27:16', 'COCA词频', 8457);
INSERT INTO `word_bank` VALUES (89825, 'en', 'incongruity', '/,ɪnkɒŋ\'gruːɪtɪ/', '不调和的, 不适宜的', 'n', 'The incongruity of her situation struck Gina with unpleasant force. (吉娜猛然意识到自己处境尴尬，心里很不舒服。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89826, 'en', 'tableland', '/\'teɪb(ə)llænd/', '高原', 'n', 'The northwestern tableland area has a continental plateau climate with long and chilly winter and cool humid summer. (西北高原地区是大陆高原气候，有漫长而寒冷的冬季，凉爽而湿润的夏季。)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89827, 'en', 'fullness', '/ˈfʊlnəs/', '满; 充满; 丰富; 成熟', 'n', 'Use a red gloss on your bottom lip to give it fullness. (下唇使用红色唇彩让它显得丰盈饱满。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14077);
INSERT INTO `word_bank` VALUES (89828, 'en', 'recoil', '/rɪˈkɔɪl/', '反跳，跳回; 退却，后退; 报应', 'vi', '...his small body jerking in recoil from the volume of his shouting. (…他小小身体在他大声的叫喊中畏缩地抽搐着。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13527);
INSERT INTO `word_bank` VALUES (89830, 'en', 'forte', '/\'fɔːteɪ; \'fɔːtɪ; fɔːt/', '长处', 'n', 'He found that running long distances was not his forte . (他发现长跑并不是他的强项。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89831, 'en', 'percussive', '/pə\'kʌsɪv/', '冲击的,叩诊的', 'adj', '...using all manner of percussive effects. (...运用各种打击乐效果。)', 5, '2026-08-06 02:27:16', '托福', NULL);
