INSERT INTO `word_bank` VALUES (89834, 'en', 'induct', '/ɪnˈdʌkt/', '使正式就任', 'vt', 'The government shoulders ethic obligation, she has to induct and maintain the rationalization of the living world. (政府在生活世界中引导和维护生活世界的合理化，肩负著伦理责任；)', 4, '2026-08-06 02:27:16', 'COCA词频', 15282);
