INSERT INTO `word_bank` VALUES (89992, 'en', 'scavenge', '/ˈskævɪndʒ/', '清除污物，打扫; （在废物中）寻觅; （动物）食腐肉', 'vt', 'Pigs scavenged among the rubbish. (猪在垃圾堆里觅食。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18279);
INSERT INTO `word_bank` VALUES (89993, 'en', 'treetop', '/ˈtri:tɒp/', '树稍', 'n', 'Boardwalks on the forest floor and the treetop level let visitors experience the rain forest up close. (在树顶上搭建的森林地面走道可以让游客近距离地接触热带雨林。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15873);
INSERT INTO `word_bank` VALUES (89994, 'en', 'ancestry', '/ˈænsestri/', '<集合词>祖先; 世家，名门', 'n', 'Most people of European or African ancestry have the \"wet\" kind: thick and sticky. (大多数欧洲或者非洲血统的人耳垢是湿的，厚的，有粘性的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11086);
INSERT INTO `word_bank` VALUES (89995, 'en', 'virginal', '/\'vɜːdʒɪn(ə)l/', '处女的, 无瑕的', 'adj', 'Somehow she\'d always been a child in his mind, pure and virginal. (不知何故，她在他心里一直是个天真无邪的孩子。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (89996, 'en', 'dulcimer', '/\'dʌlsɪmə/', '[乐] 洋琴', 'n', 'The ancestry of the piano can be traced to the early keyboard instruments of the fifteenth and sixteenth centuries -- the spinet, the dulcimer, and the virginal. (钢琴的家系可以追溯至15至16世纪早期的键盘乐器，包括小型拨弦琴、洋琴和维金娜琴。)', 4, '2026-08-06 02:27:16', '托福', NULL);
