INSERT INTO `word_bank` VALUES (90032, 'en', 'briny', '/\'braɪnɪ/', '盐水的, 咸的, 海水的', 'adj', 'All of it is growing alarmingly acidic, as the carbon dioxide spewed out by modern activities finds its way into the briny. (现代生产中喷涌而出的二氧化碳最终会融入了海水，海洋整体的酸化也令人担忧。)', 5, '2026-08-06 02:27:16', '托福', NULL);
