INSERT INTO `word_bank` VALUES (90050, 'en', 'humanist', '/ˈhju:mənɪst/', '人道主义者，人文主义者', 'n', 'Vernon said that as he watched the tsunami come ashore, he was unable to divorce the scientist in him from the humanist. (弗兰克说，当他观看到海啸逼近的时候，他不能使自己从科学家和人道主义者中脱离出来。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17724);
