INSERT INTO `word_bank` VALUES (90052, 'en', 'satirist', '/\'sætərɪst/', '讽刺作家', 'n', 'He built a reputation in the 1970s as a social satirist. (他在20世纪70年代作为社会讽刺作家而出名。)', 4, '2026-08-06 02:27:16', '托福', NULL);
