INSERT INTO `word_bank` VALUES (90069, 'en', 'ethically', '/\'eθɪklɪ/', '伦理（学）上', 'adv', 'What is technically possible and what is ethically appropriate is a matter of heated debate. (什么在技术上是可行的与什么在伦理上是适当的，这是一个激烈辩论的问题。)', 3, '2026-08-06 02:27:16', 'COCA词频', 14504);
