INSERT INTO `word_bank` VALUES (90089, 'en', 'diagonally', '/daɪ\'æɡənəlɪ/', '对角线地，斜线地', 'adv', 'Rising diagonally from the ground to the right of Venus is the band of our Milky Way Galaxy. (从地面斜对角向金星的右上方，可以看到我们的银河系的光带。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16949);
INSERT INTO `word_bank` VALUES (90090, 'en', 'rustproof', '/\'rʌs(t)pruːf/', '不锈的, 抗锈的', 'adj', 'Stainless products are always popular because they’re rustproof. (不锈钢制品因为能防锈，所以很受欢迎。)', 3, '2026-08-06 02:27:16', '托福', NULL);
