INSERT INTO `word_bank` VALUES (90098, 'en', 'plaint', '/pleɪnt/', '[诗]悲叹, 抱怨', 'n', '..a forlorn, haunting plaint. (...一种愁苦的、挥之不去的悲叹。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90099, 'en', 'waterborne', '/\'wɔːtəbɔːn/', '水上的,  水运的', 'adv', 'Because they measured success only by the number of wells built and the decline of waterborne illnesses, they missed early signs of the arsenicosis crisis. (因为他们认为的成功只是水井的数量和减少水传播的疾病，他们忽视掉了早期砷中毒所带来的危机信号。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90100, 'en', 'amazement', '/əˈmeɪzmənt/', '惊奇，惊愕，诧异', 'n', 'I stared at her in amazement. (我惊讶地盯着她。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9565);
