INSERT INTO `word_bank` VALUES (90106, 'en', 'simplistic', '/sɪmˈplɪstɪk/', '过分单纯化的; 过分简单化的; 把复杂问题搞得过于简单的', 'adj', 'This is a very simplistic approach to the problem. (这应该对该问题过分简单化的处理办法。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10950);
INSERT INTO `word_bank` VALUES (90107, 'en', 'teapot', '/ˈti:pɒt/', '茶壶', 'n', 'She upped and threw the teapot at him. (她跳起来，将茶壶向他掷去。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13234);
INSERT INTO `word_bank` VALUES (90108, 'en', 'rationally', '/\'ræʃnəlɪ/', '讲道理地，理性地', 'adv', 'Large scale revolutions attempting to change all the institutions of society at once make it impossible for anyone –including the revolutionaries –to plan rationally. (企图立即改变社会的制度而引发的大规模革命使得所有人都不能理性的计划，包括那些革命者的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15399);
