INSERT INTO `word_bank` VALUES (90110, 'en', 'importer', '/ɪmˈpɔ:tə(r)/', '进口商，进口者', 'n', 'Japan is the biggest importer of U.S. beef. (日本是美国牛肉的最大进口国。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14290);
INSERT INTO `word_bank` VALUES (90111, 'en', 'foundry', '/ˈfaʊndri/', '铸造厂', 'n', 'an iron foundry (铸铁厂)', 5, '2026-08-06 02:27:16', 'COCA词频', 18943);
INSERT INTO `word_bank` VALUES (90112, 'en', 'systematize', '/\'sɪstəmə,taɪz/', '系统化', 'v', 'This basic plugin is undoubtedly one of the important plugins to systematize the archives. (这个插件无疑是系统化归档的重要插件之一。)', 3, '2026-08-06 02:27:16', '托福', NULL);
