INSERT INTO `word_bank` VALUES (90122, 'en', 'genial', '/ˈdʒi:niəl/', '和蔼的，亲切的; 温暖的，温和的; 宜人的; 显示天才的', 'adj', 'a genial smile (亲切的微笑)', 3, '2026-08-06 02:27:16', 'COCA词频', 18074);
INSERT INTO `word_bank` VALUES (90124, 'en', 'occupancy', '/ˈɒkjəpənsi/', '占有，占领; 居住', 'n', 'Hotels in Tokyo enjoy over 90% occupancy. (东京的宾馆入住率高达90%以上。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11927);
INSERT INTO `word_bank` VALUES (90125, 'en', 'mildly', '/ˈmaɪldli/', '和善地; 轻微地; 说得委婉些; 说得好听一点', 'adv', '‘Of course I don’t mind,’ she answered mildly. (“我当然不介意。”她温和地答道。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8611);
INSERT INTO `word_bank` VALUES (90126, 'en', 'ethnographic', '/ˌeθnə\'ɡræfɪk/', '人种志的', 'adj', 'Near Amsterdam there is an ethnographic museum where one can trace the history of klomps development, to see the fully automated production process of this unique wooden shoes. (在阿姆斯特丹附近，有一个人种学博物馆，里面介绍了木屐鞋的发展历史，还能了解这种独特木鞋的整个自动化制作过程。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10042);
INSERT INTO `word_bank` VALUES (90128, 'en', 'masthead', '/\'mɑːsthed/', '桅顶, 报头', 'n', 'The bark was dressed with masthead flags only. (那条三桅帆船只用桅顶旗装饰。)', 3, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90129, 'en', 'gazette', '/gə\'zet/', '报纸, 政府的公报', 'n', 'the ‘Phoenix Gazette’ (《凤凰城报》)', 5, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90130, 'en', 'spheroidal', '/sfɪə\'rɒɪdəl/', '球状的', 'adj', 'For another, the clouds don\'t look like the disheveled spheroidal dwarf galaxies that closely orbit the Milky Way and other major spirals. (另一方面，这些星云看上去并不像结构松散的球状矮星系一样紧紧地围绕银河系和其它主要的漩涡星系的轨道运行。)', 4, '2026-08-06 02:27:16', '托福', NULL);
