INSERT INTO `word_bank` VALUES (90162, 'en', 'working', '/ˈwɜ:kɪŋ/', '（涉及）工作的; （人）有工作的; （时间）用于工作上的; （想法等）可作为基础的', 'adj', 'I shall never understand the workings of his mind (= how he thinks ) . (我永远理解不了他的想法。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8094);
