INSERT INTO `word_bank` VALUES (90164, 'en', 'contractor', '/kənˈtræktə(r)/', '订约人，承包人; 收缩物', 'n', 'We told the building contractor that we wanted a garage big enough for two cars. (我们告诉建筑承包商，我们想要一个可以停放两辆汽车的车库。)', 5, '2026-08-06 02:27:16', 'COCA词频', 3781);
INSERT INTO `word_bank` VALUES (90165, 'en', 'cubism', '/\'kjuːbɪz(ə)m/', '立体派', 'n', 'Pablo Picasso played a principal role in the early movement of cubism. (帕勃洛•毕加索在立体派早期发展中起首重要的推动作用。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90166, 'en', 'woodcarving', '/\'wʊdkɑːvɪŋ/', '木雕, 木刻', 'n', 'Masi island is famous woodcarving centre. (玛斯是该岛著名的木雕中心。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90167, 'en', 'prodigy', '/ˈprɒdədʒi/', '奇才，天才（尤指神童）; 壮举，盛况', 'n', 'The Russian tennis prodigy is well on the way to becoming the youngest world champion of all time. (这位俄罗斯网球奇才已很有望成为历史上最年轻的世界冠军。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14786);
INSERT INTO `word_bank` VALUES (90168, 'en', 'nonconformist', '/nɒnkən\'fɔːmɪst/', '不信奉英国国教的 n非国教徒', 'adj', 'Their views are nonconformist and their political opinions are extreme. (他们的看法与众不同，政治观点也很极端。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90170, 'en', 'renter', '/ˈrentə(r)/', '租贷人', 'n', 'He considers himself fortunate to be a renter in the Detroit area, where the “for sale” signs are multiplying. (他考虑以后在底特律当一名承租人，因为底特律的“租赁”业正在不断发展。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14811);
INSERT INTO `word_bank` VALUES (90171, 'en', 'claimant', '/ˈkleɪmənt/', '原告; 索取者', 'n', 'benefit claimants (救济金申请人)', 3, '2026-08-06 02:27:16', 'COCA词频', 17976);
INSERT INTO `word_bank` VALUES (90172, 'en', 'sadden', '/ˈsædn/', '使悲哀; 使伤心', 'v', 'The cruelty in the world saddens me incredibly. (世间的残酷令我悲伤不已。)', 5, '2026-08-06 02:27:16', 'COCA词频', 12741);
INSERT INTO `word_bank` VALUES (90176, 'en', 'starch', '/stɑ:tʃ/', '淀粉，含淀粉的食物; 形式主义; 古板，僵硬; 元气', 'n', 'He eats a lot of starch. (他吃大量含淀粉的食物。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13943);
INSERT INTO `word_bank` VALUES (90177, 'en', 'packer', '/\'pækə/', '包装工人, 打包机', 'n', 'Norma Jones worked as a packer in a local chemical factory. (诺玛·琼斯在本地一家化工厂作包装工。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90178, 'en', 'negate', '/nɪˈgeɪt/', '取消，使无效; 否定，否认; 使作废', 'vt', 'He warned that to negate the results of elections would only make things worse. (他警告说否定选举结果只能使事态更加恶化。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12732);
