INSERT INTO `word_bank` VALUES (90205, 'en', 'stonemason', '/\'stəʊnmeɪs(ə)n/', '石匠', 'n', 'One thinks of Amos the sheepherder, Socrates the stonemason, Omar the tentmaker . (想想牧羊人阿摩司，石匠苏格拉底，帐蓬制造人奥马尔。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90206, 'en', 'biter', '/\'baɪtə/', '咬人的动物, 骗子', 'n', 'The kids already know that biting hurts, so after removing the biter from the situation, focus all your concern on the victim. (孩子是知道咬会伤人的，因此把咬人的孩子抱离后，集中关心一下被咬的孩子。)', 4, '2026-08-06 02:27:16', '托福', NULL);
