INSERT INTO `word_bank` VALUES (90209, 'en', 'aero', '/\'eərəʊ/', '航空的,  飞行的', 'adj', 'Boeing\'s research in India will break new ground in aero structures, aerodynamics and electronic networks with a team of senior researchers, scientists and engineers. (在印度，波音公司将与资深研究人员、科学家和工程师一起开创印度航空构造学、空气动力学以及电子网络的新天地。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90210, 'en', 'cheapen', '/\'tʃiːp(ə)n/', '减价, 跌价', 'v', NULL, 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90211, 'en', 'thorny', '/ˈθɔ:ni/', '多刺的; 痛苦的; 棘手的', 'adj', '...thorny hawthorn trees. (…带刺的山楂树。)', 3, '2026-08-06 02:27:16', 'COCA词频', 13610);
INSERT INTO `word_bank` VALUES (90212, 'en', 'inchworm', '/\'ɪn(t)ʃwɜːm/', '[昆] 尺蠖', 'n', 'The adorable inchworm is really the caterpillar of the geometer moth. (可爱的尺蠖就是尺蠖毛虫。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90213, 'en', 'escalator', '/ˈeskəleɪtə(r)/', '自动扶梯', 'n', 'Take the escalator to the third floor and it\'s the last office on the left. (乘电梯到4楼，左边最后的那个办公室就是。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15323);
INSERT INTO `word_bank` VALUES (90214, 'en', 'smite', '/smaɪt/', '猛打，重击，打击', 'vt', 'The heroic leader charged into battle, ready to smite the enemy. (英勇的军官冲上战场，准备重击敌人。)', 3, '2026-08-06 02:27:16', 'COCA词频', 15012);
