INSERT INTO `word_bank` VALUES (90216, 'en', 'eyelid', '/ˈaɪlɪd/', '眼睑; 眼皮', 'n', 'His eyelids began to droop (= close, because he was sleepy ). (他的眼皮开始往下垂。)', 5, '2026-08-06 02:27:16', 'COCA词频', 8820);
INSERT INTO `word_bank` VALUES (90217, 'en', 'comfortably', '/ˈkʌmftəbli/', '舒服地; 安乐地; 充裕地', 'adv', 'The hotel is modern and comfortably furnished . (这家宾馆很现代化，家具很舒适。)', 4, '2026-08-06 02:27:16', 'COCA词频', 6998);
INSERT INTO `word_bank` VALUES (90218, 'en', 'hatchet', '/ˈhætʃɪt/', '短柄小斧; 言归于好', 'n', 'Would I feel better if I took a hatchet to her, just to end this nightmare? (如果我向她举起一把短柄斧，结束这场噩梦，我会感觉好一些吗？)', 4, '2026-08-06 02:27:16', 'COCA词频', 18605);
