INSERT INTO `word_bank` VALUES (90220, 'en', 'attributable', '/əˈtrɪbjətəbl/', '可归因于…的; 由…引起的', 'adj', '10,000 deaths a year from chronic lung disease are attributable to smoking. (每年1万个慢性肺病患者的死亡可能是由于吸烟导致的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10998);
INSERT INTO `word_bank` VALUES (90221, 'en', 'predominance', '/prɪ\'dɒmɪnəns/', '优势', 'n', '...the predominance of women in the industry. (...该产业妇女在数量上拥有的优势。)', 4, '2026-08-06 02:27:16', '托福', NULL);
