INSERT INTO `word_bank` VALUES (90328, 'en', 'purplish', '/\'pɜːplɪʃ/', '略带紫色的', 'adj', 'This year, we used the purplish tuber in taro and pumpkin tofu puffs. (这年，我们用紫色块茎中的芋头，南瓜豆腐泡。)', 5, '2026-08-06 02:27:16', '托福', NULL);
