INSERT INTO `word_bank` VALUES (90494, 'en', 'hillbilly', '/\'hɪlbɪlɪ/', '山地内部的贫农,乡下人', 'n', 'Blinking in amazement, the hillbilly drawled, \"I should have brought my wife! (乡下人惊奇地眨着眼睛，慢吞吞地说：“我应该把我的老婆带来!”)', 4, '2026-08-06 02:27:16', '托福', NULL);
