INSERT INTO `word_bank` VALUES (90533, 'en', 'relational', '/rɪ\'leɪʃ(ə)n(ə)l/', '有关系的, 亲属的', 'adj', 'One of these tables contains only traditional relational columns, while the second contains relational columns and one XML column. (这两个表的其中之一仅包含传统的关系列，而另一个包含关系列和一个 XML 列。)', 4, '2026-08-06 02:27:16', '托福', NULL);
