INSERT INTO `word_bank` VALUES (90535, 'en', 'palimpsest', '/\'pælɪm(p)sest/', '重写本', 'n', 'Some of it is lost, as the DNA palimpsest has been erased and re-written. (它们的一些已经丢失了，因为一些DNA手稿已经被擦去重写。)', 4, '2026-08-06 02:27:16', '托福', NULL);
