INSERT INTO `word_bank` VALUES (90559, 'en', 'depositor', '/dɪˈpɒzɪtə(r)/', '存放人，存款人; 寄托者; 沉淀器', 'n', 'Notice that the St. Louis memo tiptoes around the question of telling a depositor that he has a demand deposit while telling the rest of the country that he has a time deposit. (请注意，圣路易斯储备银行的备忘录一直在一个问题上遮遮掩掩，那就是把存款人的活期存款说成定期存款，欺骗国人。)', 5, '2026-08-06 02:27:16', 'COCA词频', 17637);
INSERT INTO `word_bank` VALUES (90562, 'en', 'splinter', '/ˈsplɪntə(r)/', '尖片; 碎片; 微不足道的事情; 〈美俚〉极瘦的人', 'n', 'I’ve got a splinter in my finger. (我的手指扎了一根刺。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15236);
INSERT INTO `word_bank` VALUES (90563, 'en', 'tonnage', '/\'tʌnɪdʒ/', '登记吨位, 排水量', 'n', 'A huge tonnage of bombs has already been dropped on the area. (巨大吨数的炸弹已被投到该地区。)', 4, '2026-08-06 02:27:16', '托福', NULL);
INSERT INTO `word_bank` VALUES (90564, 'en', 'seagoing', '/\'siːgəʊɪŋ/', '适于远航的,出海的', 'adj', 'a seagoing ship (远洋轮)', 4, '2026-08-06 02:27:16', '托福', NULL);
