INSERT INTO `word_bank` VALUES (90609, 'en', 'narrowly', '/ˈnærəʊli/', '狭窄地; 勉强地; 严密地; 仔细地', 'adv', 'He was narrowly defeated in the election. (他在选举中以微弱差距败北。)', 4, '2026-08-06 02:27:16', 'COCA词频', 8224);
INSERT INTO `word_bank` VALUES (90610, 'en', 'spar', '/spɑ:(r)/', '圆材，晶石', 'n', 'Meanwhile, industry, civil society groups and governments continue to spar over the application of intellectual property rights to products and genetic sequences derived from natural resources. (其间，工业、民间社会团体以及政府持续对申请产品和得自自然资源的基因序列的知识产权问题产生争论。)', 3, '2026-08-06 02:27:16', 'COCA词频', 19189);
INSERT INTO `word_bank` VALUES (90611, 'en', 'hometown', '/ˈhəʊmtaʊn/', '家乡，故乡; “home town”的变体', 'n', 'Do you like your hometown? (你喜欢你的家乡吗？)', 4, '2026-08-06 02:27:16', 'COCA词频', 5544);
INSERT INTO `word_bank` VALUES (90612, 'en', 'dough', '/dəʊ/', '生面团; 〈美俚〉钱', 'n', 'Add some raisins to the dough. (在生面团中加一些葡萄干。)', 4, '2026-08-06 02:27:16', 'COCA词频', 4442);
INSERT INTO `word_bank` VALUES (90613, 'en', 'flair', '/fleə(r)/', '天资; 天分; 眼光; 鉴别力', 'n', 'Jo has a flair for languages. (乔有语言天赋。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11519);
INSERT INTO `word_bank` VALUES (90614, 'en', 'esoteric', '/ˌesəˈterɪk/', '秘传的; 机密的; 难解的，深奥的; 限于少数人的', 'adj', '...esoteric knowledge. (…深奥难懂的知识。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14258);
