INSERT INTO `word_bank` VALUES (90617, 'en', 'elixir', '/ɪ\'lɪksə; -sɪə/', '炼金药, 不老长寿药', 'n', 'the search for the elixir of life (寻找长生不老药)', 4, '2026-08-06 02:27:16', '托福', NULL);
