INSERT INTO `word_bank` VALUES (90619, 'en', 'imprecise', '/ɪmprɪ\'saɪs/', '不精确的', 'adj', 'vague imprecise estimates (粗略的、不精确的估计)', 4, '2026-08-06 02:27:16', '托福', NULL);
