INSERT INTO `word_bank` VALUES (94978, 'en', 'retrograde', '/\'retrəgreɪd/', '倒退的；退化的；次序颠倒的；逆行；倒退；退步；倒退地；向后地', 'adj', 'The closure of the factories is seen as a retrograde step . (工厂的关闭被认为是一个退步。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
