INSERT INTO `word_bank` VALUES (94980, 'en', 'symptomatic', '/ˌsɪmptəˈmætɪk/', '有症状的; 症候的; 根据症状的', 'adj', 'These serve to show that children with mental disorders can not only be treated but can direct some of their symptomatic behavior into positive channels. (做这些是为了告诉人们，精神疾病患儿不仅是可以治疗的，而且可以将一些症状行为引导到积极的方面上。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14749);
