INSERT INTO `word_bank` VALUES (95018, 'en', 'espy', '/ɪ\'spaɪ; e-/', '看到；认出；发现；(Espy)人名；(英、法)埃斯皮', 'v', 'Here, from a window, did Guinevere espy a knight standing in a woodman\'s cart. (吉尼维尔是从这里透过窗户看到了站在樵夫车上的骑士。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95019, 'en', 'admonish', '/ədˈmɒnɪʃ/', '劝告; 训诫; （温和地）责备; 轻责', 'vt', 'They admonished me for taking risks with my health. (他们告诫我不要拿自己的健康来冒险。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12778);
INSERT INTO `word_bank` VALUES (95020, 'en', 'vacillate', '/\'væsɪleɪt/', '犹豫；踌躇；摇摆', 'v', 'She vacillates between men twice her age and men younger than she. (她在两个男人之间摇摆不定，一个年龄比她大一倍，一个比她小。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95021, 'en', 'proportionate', '/prə\'pɔːʃ(ə)nət/', '成比例的；相称的；适当的；使成比例；使相称', 'adj', 'Republics will have voting rights proportionate to the size of their economies. (各共和国将拥有与其经济规模成比例的选举权。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
