INSERT INTO `word_bank` VALUES (95049, 'en', 'cognate', '/\'kɒgneɪt/', '[地质] 同源的；同类的；同族；同根词', 'adj', 'This one branch is the Liberty of Thought: from which it is impossible to separate the cognate liberty of speaking and of writing. (这条支线就是思想的自由。 把同源的言语的自由与写作的自由和思想的自由分开是不可能的。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
