INSERT INTO `word_bank` VALUES (95053, 'en', 'pepsin', '/\'pepsɪn/', '胃蛋白酶', 'n', 'The impressively named chief cells secrete pepsinogen which, when it mixes with stomach acid, becomes an enzyme called pepsin. (而令人印象深刻的主细胞则分泌胃蛋白酶原，当它与胃酸混合时，就形成一种酶，叫做胃蛋白酶。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
