INSERT INTO `word_bank` VALUES (95057, 'en', 'codicil', '/\'kɒdɪsɪl; \'kəʊ-/', '遗嘱的附录', 'n', 'In codicil, keep your plans somewhat flexible so that you can change ships at the last minute. (在遗嘱，让您的计划一定灵活性，以便您可以更改船舶在最后一分钟。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
