INSERT INTO `word_bank` VALUES (95061, 'en', 'cartographer', '/kɑː\'tɒɡrəfə/', '制图师；地图制作者', 'n', 'This is my survey of a tumultuous landscape, done with all the uncertainty of a cartographer who does not know exactly where the boundaries of revolt begin and end. (这就是我对这片动荡之地的调查，在调查中制图师完全不能确定起义发生和结束的界限范围。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
