INSERT INTO `word_bank` VALUES (95118, 'en', 'premonition', '/ˌpri:məˈnɪʃn/', '预感，预兆; 前兆，征兆; 预先的警告（告诫），预诫', 'n', 'He had an unshakable premonition that he would die. (他有一种强烈的预感：他就要死了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18502);
INSERT INTO `word_bank` VALUES (95119, 'en', 'fretful', '/\'fretfʊl; -f(ə)l/', '焦躁的；烦燥的；起波纹的', 'adj', 'Don\'t assume your baby automatically needs feeding if she\'s fretful. (不要你的婴儿一焦躁就假定她必然需要喂食。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
