INSERT INTO `word_bank` VALUES (95122, 'en', 'perverse', '/pəˈvɜ:s/', '不正当的，堕落的; 执拗的，刚愎的; 故意作对的; 有悖常情的', 'adj', 'He gets perverse satisfaction from embarrassing people. (他通过使人难堪获得变态的满足感。)', 3, '2026-08-06 02:27:16', 'COCA词频', 10448);
INSERT INTO `word_bank` VALUES (95123, 'en', 'aviary', '/\'eɪvɪərɪ/', '鸟类饲养场；大型鸟舍', 'n', 'Already he had begun to forget them, and Shepperton soon became an extraordinary aviary, filled with birds of every species. (他已经把那些邻居们给忘记了，谢伯顿不久就变成了一个特别的鸟类饲养场，拥有各类品种的鸟。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95124, 'en', 'panegyric', '/,pænɪ\'dʒɪrɪk/', '颂词，赞颂', 'n', 'The book is a panegyric on the intoxicating effects of marijuana. (该书是一篇对大麻兴奋陶醉效应的颂词。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95125, 'en', 'obviate', '/\'ɒbvɪeɪt/', '排除；避免；消除', 'v', 'The new treatment obviates the need for surgery. (新的疗法免除了手术的必要。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
