INSERT INTO `word_bank` VALUES (95131, 'en', 'impute', '/ɪm\'pjuːt/', '归罪于，归咎于；嫁祸于', 'v', 'It is grossly unfair to impute blame to the United Nations. (把责任归咎于联合国是极不公平的。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
