INSERT INTO `word_bank` VALUES (95136, 'en', 'gruff', '/grʌf/', '（声音）粗哑的; 生硬的; （人的行为）冷淡的; 态度生硬的', 'adj', 'He picked up the phone expecting to hear the chairman\'s gruff voice. (他拿起电话等着听主席那粗哑的声音。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16754);
