INSERT INTO `word_bank` VALUES (95140, 'en', 'clamorous', '/\'klæmərəs/', '吵闹的；大声要求的', 'adj', 'There is always a clamorous din when I go to visit my father. (每当我去看视父亲的的时候，总有一个声音在那里大喊大叫。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
