INSERT INTO `word_bank` VALUES (95142, 'en', 'complacent', '/kəmˈpleɪsnt/', '自满的; 自鸣得意的; 踌躇满志; 志得意满', 'adj', 'There’s a danger of becoming complacent if you win a few games. (赢了几场比赛可能就会变得沾沾自喜。)', 4, '2026-08-06 02:27:16', 'COCA词频', 14991);
INSERT INTO `word_bank` VALUES (95143, 'en', 'solicitude', '/sə\'lɪsɪtjuːd/', '焦虑；渴望；担心', 'n', 'Wherefore, I strongly advise you, my lords, to put aside all care and solicitude and to receive readily the most holy Body and Blood of our Lord Jesus Christ in holy commemoration of Him. (为此，我强烈地建议你们，大人，把（对此世的）关心和渴望放到一边并接受我们的主基督在祂神圣的纪念仪式中已经是最神圣的身体和血。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95144, 'en', 'prim', '/prɪm/', '拘谨的；整洁的；呆板的；使显得一本正经；把…打扮得整整齐齐；(Prim)人名；(法、德、匈、捷、瑞典、西、葡)普里姆', 'adj', 'She looked prim and nervous in her best hat and coat. (她戴着最好的帽子并穿着最好的外套，显得拘谨不安。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
