INSERT INTO `word_bank` VALUES (95165, 'en', 'philanthropic', '/ˌfɪlən\'θrɒpɪk/', '博爱的，慈善的', 'adj', 'Some of the best services for the seniors are sponsored by philanthropic organizations. (一些一流老人服务机构是由慈善组织资助的。)', 5, '2026-08-06 02:27:16', 'COCA词频', 15795);
