INSERT INTO `word_bank` VALUES (95172, 'en', 'atone', '/ə\'təʊn/', '赎罪；弥补；偿还', 'v', 'He felt he had atoned for what he had done to his son. (他觉得他已弥补曾对儿子所做的错事。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
