INSERT INTO `word_bank` VALUES (95174, 'en', 'demure', '/dɪ\'mjʊə; dɪ\'mjɔː/', '端庄的；娴静的；严肃的；假装正直的；(Demure)人名；(法)德米尔', 'adj', 'Old photos of Maggie show her young and demure. (老照片上的玛吉显得年轻而又端庄娴静。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
