INSERT INTO `word_bank` VALUES (95182, 'en', 'spate', '/speɪt/', '大量; 发洪水，（河流）暴涨; 大雨', 'n', 'With the drought and wildfires in Russia and the floods in Pakistan, the world\'s spate of weird weather is already taking its toll on global food prices. (伴随着俄罗斯发生的大火和干旱以及在巴基斯坦的洪水,世界的一连串的怪异天气已经造成了全球粮食价格的上涨。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15242);
INSERT INTO `word_bank` VALUES (95459, 'en', 'blithesome', '/\'blaɪðsəm/', '愉快的', 'adj', 'She\'s self-confidence, talking relaxable and make others relaxable and blithesome, let you know life is so lively. (她很自信，说话很放松也让别人放松、愉快，让人觉得生活充满希望。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95460, 'en', 'cerebellum', '/,serɪ\'beləm/', '[解剖] 小脑', 'n', 'Damage to the cerebellum can disrupt motor activity in other ways. (小脑损伤可能连带影响运动机能。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
