INSERT INTO `word_bank` VALUES (95591, 'en', 'inventive', '/ɪnˈventɪv/', '发明的; 善于发明的; 有创造力的; 独出心裁的', 'adj', 'It inspired me to be more inventive with my own cooking. (它激励我在自己烹饪时更具创造力。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12610);
