INSERT INTO `word_bank` VALUES (95600, 'en', 'usurious', '/juː\'ʒʊərɪəs; juː\'zj-/', '高利贷的', 'adj', 'Every debt he owed in the world, including the pawnshop, with its usurious interest, amounted to less than a hundred dollars. (他在世界上欠下的每一笔帐，包括高利贷的当铺债务，加在一起也不到一百元。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95601, 'en', 'forthright', '/ˈfɔ:θraɪt/', '直率的; 直接的', 'adj', 'She answered in her usual forthright manner . (她以一贯的直率作了回答。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15772);
INSERT INTO `word_bank` VALUES (95602, 'en', 'inviolable', '/ɪn\'vaɪələb(ə)l/', '不可侵犯的；神圣的；不可亵渎的', 'adj', 'The game had a single inviolable rule: obstacles were to be overcome, not circumvented. (这个游戏有一个单一的不可违反的规则：困难是被克服的，不是被回避的。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
