INSERT INTO `word_bank` VALUES (95608, 'en', 'stupor', '/\'stjuːpə/', '昏迷，恍惚；麻木', 'n', 'We found him lying at the bottom of the stairs in a drunken stupor . (我们发现他躺在楼梯口，醉得不省人事。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95609, 'en', 'inhume', '/ɪn\'hjuːm/', '埋葬；土葬', 'v', 'It\'s time to inhume the quondam and move above to a current tomorrow, \" it says.\" (从现在开始，埋葬过去，走向新的明天。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
