INSERT INTO `word_bank` VALUES (95617, 'en', 'benediction', '/,benɪ\'dɪkʃ(ə)n/', '祝福；赐福；恩赐；祈求上帝赐福的仪式', 'n', 'The minister pronounced the benediction. (牧师做了赐福祈祷。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
