INSERT INTO `word_bank` VALUES (95619, 'en', 'volitive', '/\'vɒlɪtɪv/', '意志的；表示意志的；发自意志的', 'adj', NULL, 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (95620, 'en', 'introspect', '/,ɪntrə(ʊ)\'spekt/', '反省；内省', 'v', 'The point is, if you just can\'t get things done, and this has been going on for a long time, then it\'s time to self-introspect and find out what this is all about. (重点是，如果你连完成工作都不能做到，而且这已经花费了很长一段时间，那么是时候该进行自身的反省并找出关于这个的全部原因。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
