INSERT INTO `word_bank` VALUES (95625, 'en', 'calumniate', '/kə\'lʌmnɪeɪt/', '诽谤；中伤；诬蔑', 'v', NULL, 4, '2026-08-06 02:27:16', 'SAT', NULL);
