INSERT INTO `word_bank` VALUES (95628, 'en', 'equiangular', '/,iːkwɪ\'æŋgjʊlə; e-/', '等角的', 'adj', 'If you test by the triangle\'s angles, possible types are right, acute, obtuse, or equiangular. (如果您用三角形的角度进行测试，那么可能的类型是直角、锐角、钝角或等角三角形。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
