INSERT INTO `word_bank` VALUES (95662, 'en', 'sophism', '/\'sɒfɪz(ə)m/', '诡辩', 'n', 'It is sophism to connect physiological needs with morality. (片面地把生理问题与所谓“道德”混同起来，根本上就是诡辩。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
