INSERT INTO `word_bank` VALUES (96048, 'en', 'quadrilateral', '/,kwɒdrɪ\'læt(ə)r(ə)l/', '四边形；四边形的', 'n', 'The quadrilateral takes eight arguments representing the four points of the quadrilateral. (四边形接受八个参数，代表的是这个四边形的四个顶点。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
