INSERT INTO `word_bank` VALUES (96097, 'en', 'anhydrous', '/æn\'haɪdrəs/', '无水的', 'adj', 'It is prepared by reacting anhydrous ammonia and carbon dioxide gas under very high pressure in the presence of a suitable catalyst. (它是在某种催化剂参与下，由无水氨和二氧化碳气体在高压条件下反应生成的。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
