INSERT INTO `word_bank` VALUES (96101, 'en', 'archbishop', '/ˌɑ:tʃˈbɪʃəp/', '大主教; 主教长', 'n', 'When I speak to my archbishop in San Francisco and his role is to try to change my mind on the subject, well then he is exercising his pastoral duty to me as one of his flock. (我在旧金山和我的大主教谈话时，他的任务是努力改变我在那个主题上的看法，那时，他是把我当作他的一只羔羊在实践其牧师的职责。)', 3, '2026-08-06 02:27:16', 'COCA词频', 13904);
