INSERT INTO `word_bank` VALUES (96471, 'en', 'hoary', '/\'hɔːrɪ/', '久远的，古老的；灰白的', 'adj', 'Not that hoary old chestnut (= old idea, joke, remark etc ) again. (别再说那老掉牙的话了。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96472, 'en', 'isothermal', '/,aɪsəʊ\'θɜːməl/', '等温的；等温线的；等温线', 'adj', 'And you know, you could have a reversible engine with lots and lots of steps, but you could always break them down into some sequence of adiabatic and isothermal steps. (你们知道，我们可以设计一个由，很多很多个,循环步骤的热机，但是总可以把它分割成,一系列的绝热,和等温过程。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
