INSERT INTO `word_bank` VALUES (96476, 'en', 'wean', '/wi:n/', '使断奶; 使断念', 'vt', 'When would be the best time to start weaning my baby? (什么时候开始给我的孩子断奶最好呢？)', 3, '2026-08-06 02:27:16', 'COCA词频', 14048);
