INSERT INTO `word_bank` VALUES (96480, 'en', 'polyglot', '/\'pɒlɪglɒt/', '通晓数种语言的人；用通晓数种语言记载的书；通数国语言，数国语言的', 'n', '...Chicago\'s polyglot population. (...芝加哥的多语种人口。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96481, 'en', 'antagonist', '/ænˈtægənɪst/', '敌手，反对者; <解>对抗肌，拮抗肌; <药>对抗药; （戏剧，小说等的）反面人物', 'n', 'Spassky had never previously lost to his antagonist. (斯帕斯基以前从未败给过他的敌手。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16608);
