INSERT INTO `word_bank` VALUES (96503, 'en', 'equivocate', '/ɪ\'kwɪvəkeɪt/', '说模棱两可的话；支吾， 躲闪；推诿；含糊其词', 'v', 'He is equivocating a lot about what is going to happen if and when there are elections. (他含含糊糊地说着很多如果进行选举会发生的状况。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
