INSERT INTO `word_bank` VALUES (96505, 'en', 'endemic', '/enˈdemɪk/', '某地特有的; （尤指疾病）地方性的; 风土的; （动，植物）某些特产的', 'adj', 'Violent crime is now endemic in parts of Chicago. (芝加哥一些地区暴力犯罪成患。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12408);
