INSERT INTO `word_bank` VALUES (96507, 'en', 'sonorous', '/\'sɒn(ə)rəs; sə\'nɔːrəs/', '响亮的；作响的；能发出响亮声音的', 'adj', 'a sonorous voice (洪亮的嗓音)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
