INSERT INTO `word_bank` VALUES (96510, 'en', 'monocracy', '/mə\'nɒkrəsɪ/', '独裁政治', 'n', 'The citizen politics is a kind of monocracy politics, and the law is the body of people\'s will. (国民政治是法治政治，法律是人民意志的体现；国民政治的实现、维持和运用。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96511, 'en', 'beget', '/bɪ\'get/', '产生；招致；引起；当…的父亲', 'v', 'Hunger begets crime. (饥饿滋生犯罪。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
