INSERT INTO `word_bank` VALUES (96514, 'en', 'demur', '/dɪ\'mɜː/', '反对；抗辩；提出异议；异议；反对', 'v', 'They demurred politely, but finally agreed to stay. (他们礼貌地推却，但最后还是同意留下。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96515, 'en', 'incommodious', '/,ɪnkə\'məʊdɪəs/', '不便的；狭窄的', 'adj', 'I awoke with stiff and cramped muscles from having slept long on the incommodious seat of a day coach. (由于在座席客车不舒服的座位上睡了太久，我肌肉僵硬麻痹的醒来。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
