INSERT INTO `word_bank` VALUES (96518, 'en', 'facetious', '/fə\'siːʃəs/', '诙谐的；爱开玩笑的；滑稽的；(尤指在不合适的时候)开玩笑的', 'adj', 'Don’t be so facetious! (别这么乱开玩笑！)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
