INSERT INTO `word_bank` VALUES (96527, 'en', 'harbinger', '/ˈhɑ:bɪndʒə(r)/', '预言者，预兆', 'n', 'The November air stung my cheeks, a harbinger of winter. (11月的空气刺痛了我的脸颊，这是冬天要来的先兆。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16820);
INSERT INTO `word_bank` VALUES (96528, 'en', 'aphorism', '/\'æfərɪz(ə)m/', '格言；警句', 'n', 'It\'s one thing to forget the past, with predictable consequences, as the favorite aphorism goes. But what about those who refuse to comprehend the present? (正如格言所说，展望未来，忘记过去。话是这样说，但是那些拒绝理解现在的人怎么办呢？)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96530, 'en', 'afoot', '/əˈfʊt/', '徒步的（地）; 正在进行的（地）; 活动着的（地）; 不对劲的（地）', 'adj', 'Everybody knew that something awful was afoot. (每个人都知道糟糕的事在酝酿之中。)', 5, '2026-08-06 02:27:16', 'COCA词频', 18078);
INSERT INTO `word_bank` VALUES (96531, 'en', 'dogmatic', '/dɒgˈmætɪk/', '教条的; 固执己见的; 武断的', 'adj', 'Her staff find her bossy and dogmatic. (她的员工认为她爱指挥别人而且自以为是。)', 5, '2026-08-06 02:27:16', 'COCA词频', 17104);
