INSERT INTO `word_bank` VALUES (96603, 'en', 'inscrutable', '/ɪnˈskru:təbl/', '不可理解的，谜一样的; 神妙莫测', 'adj', 'He stood silent and inscrutable. (他静静地站着，让人难以捉摸。)', 3, '2026-08-06 02:27:16', 'COCA词频', 19319);
