INSERT INTO `word_bank` VALUES (96629, 'en', 'auburn', '/ˈɔ:bən/', '赤褐色的; 红褐色的', 'adj', 'She let her short blonde perm grow shoulder-length and dyed it auburn. (她任其金色短烫发长到齐及肩长，而后染成赤褐色。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19389);
