INSERT INTO `word_bank` VALUES (96640, 'en', 'euphonious', '/juː\'fəʊnɪəs/', '悦耳的', 'adj', 'The sound of whistle is euphonious , emotional, and melodic. (口哨的音色悦耳动听，抒情性极强，极富歌唱性。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96641, 'en', 'acrid', '/ˈækrɪd/', '辛辣的; 刺鼻的; （性格、态度、言词等）刻薄的; 尖刻的', 'adj', 'a cloud of acrid smoke (一团刺鼻的烟雾)', 5, '2026-08-06 02:27:16', 'COCA词频', 19584);
INSERT INTO `word_bank` VALUES (96642, 'en', 'ado', '/ə\'duː/', '忙乱，纷扰，麻烦', 'n', 'So without further ado, I’ll now ask Mr Davis to open the debate. (不再多说了，现在我请戴维斯先生开始辩论。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96643, 'en', 'ethics', '/\'eθɪks/', '伦理学; 道德规范; 伦理学著作; 道德规范( ethic的名词复数 ); 道德体系; 行为准则; 伦理学', 'n', 'Refugee workers said such action was a violation of medical ethics. (难民工作者称这种行为违背了医学道德。)', 4, '2026-08-06 02:27:16', 'COCA词频', 3259);
INSERT INTO `word_bank` VALUES (96644, 'en', 'isochronous', '/aɪ\'sɒkrənəs/', '[物] 等时的；等步的', 'adj', 'In the new period, the studies of this issue by scholars both in and out of China are isochronous , with more and more achievements and different voices coming out. (进入新时期以来，大陆学者和港台、海外汉学界对这一问题的探索和论证基本上趋于同步了，越来越多的研究成果和不同声音浮出水面。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
