INSERT INTO `word_bank` VALUES (96646, 'en', 'nausea', '/ˈnɔ:ziə/', '作呕; 恶心; 反胃; 极度厌恶', 'n', 'I was overcome with a feeling of nausea. (我感到一阵恶心。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9526);
INSERT INTO `word_bank` VALUES (96647, 'en', 'semblance', '/ˈsembləns/', '外表，外观; 类似; 假装; 副本，拷贝', 'n', 'She was trying to get her thoughts back into some semblance of order . (她想稍微理出个头绪来。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13598);
INSERT INTO `word_bank` VALUES (96648, 'en', 'effectual', '/ɪ\'fektʃʊəl; -tjʊəl/', '奏效的；会应验的；有法律效力的', 'adj', 'This is the only effectual way to secure our present and future happiness. (这是确保我们现在和未来幸福的唯一有效途径。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
