INSERT INTO `word_bank` VALUES (96674, 'en', 'irrevocable', '/ɪ\'revəkəb(ə)l/', '不可改变的；不能取消的；不能挽回的', 'adj', 'Think about the situation carefully before you take an irrevocable step. (在你踏出不能回头的一步之前要三思。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96675, 'en', 'procrastinate', '/prə(ʊ)\'kræstɪneɪt/', '耽搁，延迟', 'v', 'People often procrastinate when it comes to paperwork. (遇到文书工作，人们常常会拖拖拉拉。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (96676, 'en', 'pare', '/peə(r)/', '削皮; 削减; 修剪（指甲等）', 'vt', 'Pare the brown skin from the meat with a very sharp knife. (用一把非常锋利的刀削掉肉上褐色的皮。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13623);
