INSERT INTO `word_bank` VALUES (96678, 'en', 'despicable', '/dɪˈspɪkəbl/', '可鄙的，卑鄙的', 'adj', 'It’s despicable the way he treats those kids. (他那样对待那些孩子，真卑鄙。)', 3, '2026-08-06 02:27:16', 'COCA词频', 16994);
