INSERT INTO `word_bank` VALUES (96960, 'en', 'incumbent', '/ɪnˈkʌmbənt/', '在职的; 义不容辞的', 'adj', NULL, 3, '2026-08-06 02:27:16', 'COCA词频', 9414);
