INSERT INTO `word_bank` VALUES (96973, 'en', 'noisome', '/\'nɒɪs(ə)m/', '恶臭的；有害的', 'adj', 'noisome smells (令人生厌的气味)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
