INSERT INTO `word_bank` VALUES (96976, 'en', 'vindictive', '/vɪnˈdɪktɪv/', '怀有或显示报复心的; 恶意的，怀恨的; 惩罚的', 'adj', 'a bitter and vindictive old man (充满仇恨和报复心的老人)', 4, '2026-08-06 02:27:16', 'COCA词频', 19131);
INSERT INTO `word_bank` VALUES (96977, 'en', 'extricate', '/ˈekstrɪkeɪt/', '使摆脱困难，脱身', 'vt', 'It represents a last-ditch attempt by the country to extricate itself from its economic crisis. (这是该国摆脱经济危机的最后一搏。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17311);
