INSERT INTO `word_bank` VALUES (96998, 'en', 'hiatus', '/haɪˈeɪtəs/', '裂隙; 缺漏; 脱漏; 间断', 'n', 'Diplomatic efforts to reach a settlement resume today after a two-week hiatus. (在两周间歇后，为达成解决方案而进行的外交努力于今天重新开始。)', 3, '2026-08-06 02:27:16', 'COCA词频', 15587);
