INSERT INTO `word_bank` VALUES (97000, 'en', 'slovenly', '/\'slʌv(ə)nlɪ/', '懒散的；不整洁的；马虎的；邋遢地；马虎地；不整洁地', 'adj', 'slovenly habits (邋里邋遢的习惯)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
