INSERT INTO `word_bank` VALUES (97004, 'en', 'cauterize', '/\'kɔːtəraɪz/', '烧灼；腐蚀；使麻木（等于cauterise）', 'v', 'He cauterized the wound with a piece of red-hot iron. (他用一块烧红的烙铁来给伤口进行烧灼治疗。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
