INSERT INTO `word_bank` VALUES (97035, 'en', 'decoy', '/ˈdi:kɔɪ/', '诱饵，诱鸟; 圈套; 诱捕', 'n', 'Officer Langley acted as a decoy to catch the rapist. (警员兰利充当诱饵来抓捕那名强奸犯。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11110);
