INSERT INTO `word_bank` VALUES (97151, 'en', 'prudential', '/prʊ\'denʃ(ə)l/', '谨慎的；明辨的', 'adj', 'It provides for strong prudential, capital, and business conduct regulation of all dealers and other major participants in the derivatives markets. (它对所有的交易员和衍生品市场的主要参与者规定了严格的审慎规则、资本金和业务规则。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
