INSERT INTO `word_bank` VALUES (97499, 'en', 'egocentric', '/,egə(ʊ)\'sentrɪk; iː-/', '[心理] 自我中心的；利己主义的；利己主义者', 'adj', 'He was egocentric, a man of impulse who expected those around him to serve him. (他自我中心，易冲动，希望周围的人为他服务。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
