INSERT INTO `word_bank` VALUES (97502, 'en', 'intercession', '/,ɪntə\'seʃ(ə)n/', '调解；说情；仲裁', 'n', 'His intercession could be of help to the tribe. (他的调解会对该部落有帮助。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97503, 'en', 'archetype', '/ˈɑ:kitaɪp/', '典型; 原型', 'n', 'He came to this country 20 years ago and is the archetype of the successful Asian businessman. (他20年前来到这个国家，是成功的亚裔商人的典型。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16201);
