INSERT INTO `word_bank` VALUES (97506, 'en', 'oblique', '/əˈbli:k/', '斜，倾斜的', 'adj', 'an oblique glance (斜瞥)', 5, '2026-08-06 02:27:16', 'COCA词频', 15488);
