INSERT INTO `word_bank` VALUES (97509, 'en', 'morbid', '/ˈmɔ:bɪd/', '（兴趣、精神、思想等）病态的; 疾病的; 有成见的; 令人毛骨悚然的，恐怖的', 'adj', 'The trip was made all the worse by Frankie’s morbid fear of flying. (弗朗基对坐飞机有种病态的恐惧，使得旅途变得更加糟糕。)', 5, '2026-08-06 02:27:16', 'COCA词频', 16213);
INSERT INTO `word_bank` VALUES (97510, 'en', 'sinecure', '/\'sɪnɪkjʊə(r)/', '闲职；挂名职务', 'n', 'She found him an exalted sinecure as a Fellow of the Library of Congress. (她给他找了一个级别很高的闲职：国会图书馆研究员。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97511, 'en', 'opulent', '/ˈɒpjələnt/', '富裕的; 豪华的; <正>富足的; 繁茂的', 'adj', 'evening dresses in opulent fabrics (用华丽织物做成的晚礼服)', 4, '2026-08-06 02:27:16', 'COCA词频', 17357);
