INSERT INTO `word_bank` VALUES (97518, 'en', 'querulous', '/\'kwerʊləs; \'kwerjʊləs/', '易怒的，暴躁的；爱发牢骚的，抱怨的；爱挑剔的', 'adj', '‘But why can’t I go?’ he said in a querulous voice. (“可是为什么我不能去呢？”他抱怨道。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97519, 'en', 'turpitude', '/\'tɜːpɪtjuːd/', '卑鄙；奸恶', 'n', 'Let every declamation turn upon the beauty of liberty and virtue, and the deformity, turpitude, and malignity of slavery and vice. (让每一篇演讲都来谈自由和道德之美，都来谈奴役和邪恶之丑陋、卑鄙和恶毒。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97520, 'en', 'lambaste', '/læm\'beɪst/', '痛打；严责；鞭打', 'v', 'And you can be sure that when the referee cheats our boys, I\'ll be ready to lambaste him. (而且你可以放心，如果裁判对孩子们不公平，我会公开斥责他。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97521, 'en', 'cogitate', '/\'kɒdʒɪteɪt/', '仔细考虑；谋划', 'v', NULL, 4, '2026-08-06 02:27:16', 'SAT', NULL);
