INSERT INTO `word_bank` VALUES (97523, 'en', 'indelible', '/ɪnˈdeləbl/', '擦不掉的; 永久的，持久的; 不可磨灭', 'adj', 'Her words left an indelible impression on me for years to come. (她的话多年来我都难以忘怀。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16020);
