INSERT INTO `word_bank` VALUES (97525, 'en', 'refulgent', '/rɪ\'fʌldʒ(ə)nt/', '辉煌的；灿烂的', 'adj', 'Answer: Anyone can use a happy feeling to wish a refulgent result. (答：任何人都可以用幸福的心情期待辉煌的成果。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
