INSERT INTO `word_bank` VALUES (97535, 'en', 'avarice', '/\'æv(ə)rɪs/', '贪婪，贪财', 'n', 'He paid a month\'s rent in advance, just enough to satisfy the landlord\'s avarice. (他预交了一个月的房租，正好满足了房东的贪心。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
