INSERT INTO `word_bank` VALUES (97642, 'en', 'imperil', '/ɪmˈperəl/', '使陷于危险，危及', 'vt', 'Tax increases now might imperil economic recovery. (目前提高税收可能会危及经济的复苏。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18257);
INSERT INTO `word_bank` VALUES (97643, 'en', 'acclimate', '/\'æklɪmeɪt; ə\'klaɪmət/', '服水土；适应新环境', 'v', 'Colleges have been slow to adjust to the challenges they’ve encountered, but are beginning to try new strategies, both to better acclimate students and to deal with the application problems. (学校在适应他们遇到的挑战上已经慢了，但也开始尝试一些新策略，在让学生更好的适应环境和处理入学申请问题上。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97644, 'en', 'accentuate', '/əkˈsentʃueɪt/', '强调，着重指出; 重读; 给…加上重音符号', 'vt', 'The photograph seemed to accentuate his large nose. (照片似乎突出了他的大鼻子。)', 4, '2026-08-06 02:27:16', 'COCA词频', 11144);
INSERT INTO `word_bank` VALUES (97645, 'en', 'intangible', '/ɪnˈtændʒəbl/', '触不到的; 难以理解的; 无法确定的', 'adj', 'The island has an intangible quality of holiness. (该岛屿有一种难以形容的神圣感。)', 5, '2026-08-06 02:27:16', 'COCA词频', 14351);
