INSERT INTO `word_bank` VALUES (97648, 'en', 'repentant', '/rɪ\'pentənt/', '悔改的；后悔的', 'adj', 'He was feeling guilty and depressed, repentant and scared. (他现在觉得既内疚又沮丧，既悔恨又害怕。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
