INSERT INTO `word_bank` VALUES (97660, 'en', 'lactose', '/\'læktəʊz; -s/', '[有化] 乳糖', 'n', 'Somewhat less than 40% of people in the world retain the ability to digest lactose after childhood. (全世界大约不到40%的成年人能够在童年过后保留消化乳糖的能力。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
