INSERT INTO `word_bank` VALUES (97665, 'en', 'arbiter', '/ˈɑ:bɪtə(r)/', '\"[法', 'n', 'The European Court of Justice will be the final arbiter (=  make the final decision  ) in the dispute. (欧洲法庭将对这宗争端作出最终裁决。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15469);
