INSERT INTO `word_bank` VALUES (97668, 'en', 'effusive', '/ɪ\'fjuːsɪv/', '流出的；感情横溢的', 'adj', 'Our host gave us an effusive welcome. (主人热情地欢迎我们。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97669, 'en', 'aggrandize', '/ə\'grændaɪz/', '增加；夸大；强化', 'v', 'At the dinner table, my father would go on and on, showing off, aggrandizing himself. (吃饭时我父亲总是不停地夸耀和吹嘘自己。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97670, 'en', 'shiftless', '/\'ʃɪftlɪs/', '偷懒的；无计谋的；无能的', 'adj', 'In retrospect, I was a sad little boy and a standard-issue, shiftless, egotistical, dejected teen-ager. (回顾往事，我曾是一个悲哀的小男孩，一个无能的、任性的、沮丧的标准问题少年。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
