INSERT INTO `word_bank` VALUES (97676, 'en', 'trenchant', '/\'tren(t)ʃ(ə)nt/', '尖刻的；锐利的；苛刻的；锋利的（名词trenchancy，副词trenchantly）；(Trenchant)人名；(法)特朗尚', 'adj', 'Stockman became one of the President’s most trenchant critics. (斯托克曼成了总统最尖锐的批评者之一。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97677, 'en', 'cadaver', '/kəˈdævə(r)/', '尸体', 'n', 'Cadavers are used to teach med students surgical skills and anatomy. (尸体是教授医学院学生外科手术技术和解剖用的。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17338);
INSERT INTO `word_bank` VALUES (97678, 'en', 'collusion', '/kəˈlu:ʒn/', '共谋，勾结，串通', 'n', 'He found no evidence of collusion between record companies and retailers. (他找不出唱片公司与零售商互相勾结的证据。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17096);
