INSERT INTO `word_bank` VALUES (97680, 'en', 'relent', '/rɪˈlent/', '动怜悯心; 发慈悲心', 'vi', 'At last her father relented and came to visit her. (最后她父亲的态度软化，去看了她。)', 4, '2026-08-06 02:27:16', 'COCA词频', 16067);
INSERT INTO `word_bank` VALUES (97681, 'en', 'neutralization', '/,njuːtrəlaɪ\'zeɪʃən/', '[化学] 中和；[化学] 中和作用；中立状态', 'n', 'serum neutralization; (血清中和；)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
