INSERT INTO `word_bank` VALUES (97683, 'en', 'lingual', '/\'lɪŋgw(ə)l/', '语言的；舌的，舌音的；舌音，舌音字', 'adj', 'Her dentist advised that the problem might be coming from her thicker-than-average lingual frenulum. (她的牙医说口语水平上不去的原因可能是她的舌系带比一般人的要厚。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97684, 'en', 'fallow', '/ˈfæləʊ/', '犁过而未播种的，休闲的，（指耕地）未经耕作的', 'adj', 'They let the land lie fallow for a year. (他们让土地休耕一年。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19159);
INSERT INTO `word_bank` VALUES (97685, 'en', 'bigamy', '/\'bɪgəmɪ/', '重婚罪，重婚', 'n', 'During her life Elizabeth Barrett Browning conjectured that Browning would indulge in some \"feeble bigamy\" after her death. (伊丽莎白·巴雷特·勃朗宁在生时推测丈夫在她死后会陷入“虚弱的重婚罪”里。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (97686, 'en', 'benignity', '/bɪ\'nɪɡnətɪ/', '仁慈；善举', 'n', 'We now of no scripture which records the pure benignity of the gods on a New England winter night. (但没有一本书记录了新英格兰的冬夜，尽管它是上天仁慈的恩惠。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
