INSERT INTO `word_bank` VALUES (97991, 'en', 'palliate', '/\'pælɪeɪt/', '减轻；掩饰；辩解', 'v', 'Chosen carefully, the oils may not only palliate but also cure the condition. (如果仔细挑选，挑到的精油不仅可以缓和症状，还可以治愈疾病。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
