INSERT INTO `word_bank` VALUES (97996, 'en', 'desiccate', '/\'desɪkeɪt/', '变干', 'v', 'The device was able to desiccate the salty water and to condense the moisture into drinkable water. (这个装置能先把盐水蒸干，再让水蒸气冷凝成可饮用的水。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
