INSERT INTO `word_bank` VALUES (98038, 'en', 'attenuate', '/ə\'tenjʊeɪt/', '减弱的；稀薄的；细小的；使减弱；使纤细', 'adj', 'The repetition of symbols was to be enough, without trauma, as well, perhaps, to attenuate it, or even jar it altogether loose from her memory. (象征的重复快要足够，即便没有可能的从她记忆中流出的创伤，去减弱它去刺激它。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
