INSERT INTO `word_bank` VALUES (98047, 'en', 'commodious', '/kə\'məʊdɪəs/', '宽敞的；方便的', 'adj', '“The Coffee houses particularly are very commodious for a free Conversation, and for reading at an easie Rate all manner of printed News,” noted one observer. (“尤其是咖啡馆，是一个非常宽敞的自由交谈之处，来阅读与评论形形色色的印刷新闻”，一个观察员指出。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
