INSERT INTO `word_bank` VALUES (98054, 'en', 'jocose', '/dʒə\'kəʊs/', '诙谐的；开玩笑的', 'adj', 'Telling a lie as a joke or to fool someone is a harmless type of lie, also known as a jocose lie. (开玩笑或捉弄人般地说谎是无害的谎言，也称为戏虐性的谎言。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
