INSERT INTO `word_bank` VALUES (98064, 'en', 'obtuse', '/əbˈtju:s/', '迟钝的；圆头的；不锋利的', 'adj', '‘But why?’ said Charles, being deliberately obtuse. (“但是为什么呢？”查尔斯故意傻傻地说道。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
