INSERT INTO `word_bank` VALUES (98088, 'en', 'vermin', '/\'vɜːmɪn/', '害虫；寄生虫；歹徒', 'n', 'The beds were filthy and full of vermin. (那些床铺肮脏不堪，而且爬满了虫子。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
