INSERT INTO `word_bank` VALUES (98172, 'en', 'blight', '/blaɪt/', '凋萎病; 坏因素; 毁坏; 衰退', 'n', 'All you can do to prevent potato blight is keep an eye on your crops. (为预防马铃薯枯萎病你惟一能做的就是留意你的庄稼。)', 4, '2026-08-06 02:27:16', 'COCA词频', 15661);
