INSERT INTO `word_bank` VALUES (98174, 'en', 'vocative', '/\'vɒkətɪv/', '呼格的；称呼的；呼格', 'adj', 'Case: The category of case is prominent in the grammar of Latin, with six distinctions of nominative, vocative, accusative, genitive, dative and ablative. (格范畴在拉丁语语法里是很显著的。它有六种格：主格，呼格，宾格，属格，与格，离格。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (98175, 'en', 'homily', '/ˈhɒməli/', '（长篇）说教; 讲道，宣道', 'n', '...a receptive audience for his homily on moral values. (...乐于倾听他关于道德价值观说教的观众。)', 3, '2026-08-06 02:27:16', 'COCA词频', 18534);
INSERT INTO `word_bank` VALUES (98176, 'en', 'derange', '/dɪ\'reɪn(d)ʒ/', '扰乱；使错乱；使发狂', 'v', 'Whatever you do, don\'t let the stress derange owe head. (但无乱咋样，无所不能让压力使得你精神错乱。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
