INSERT INTO `word_bank` VALUES (98179, 'en', 'impenitent', '/ɪm\'penɪt(ə)nt/', '顽固的人；不知悔改的人；顽固的；不知悔改的', 'n', 'Endless, of the impenitent and unbelieving. (无止境的，对不知悔改的和不信。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
