INSERT INTO `word_bank` VALUES (98467, 'en', 'troubadour', '/\'truːbədɔː/', '行吟诗人；民谣歌手', 'n', 'I needed to be with people who admired my long hair and troubadour credentials, you see. (因为我想要与赞赏我的长头发的人在一起，然后让他们看到我真的是一位有实力的行呤歌手。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (98468, 'en', 'undersize', '/\'ʌndə\'saiz/', '不够大的；小于一般尺寸的；尺寸不足', 'adj', 'Conrad Anker, Brady Robinson and Jimmy Chin were confined to their undersize two - person portal edge several thousand feet up on the face. (康拉德•安科尔，布雷迪•罗宾逊和麦展只限于他们的尺寸不足二人入口边缘的数千英尺起来就面对。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
