INSERT INTO `word_bank` VALUES (98500, 'en', 'auricle', '/\'ɔːrɪk(ə)l/', '耳廓；外耳；心耳', 'n', 'Also known as the auricle, it works like a funnel, directing sounds into the ear canal. (耳廓也被称为外耳，能起到漏斗一样功用，将声音导入耳道。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
