INSERT INTO `word_bank` VALUES (98507, 'en', 'presumption', '/prɪˈzʌmpʃn/', '推测，设想; 放肆，傲慢; <律>推定', 'n', 'She was enraged by his presumption. (她被他的放肆激怒了。)', 5, '2026-08-06 02:27:16', 'COCA词频', 10134);
INSERT INTO `word_bank` VALUES (98508, 'en', 'tirade', '/taɪˈreɪd/', '激烈的长篇指责或演说', 'n', 'Now I fully recognize that I’m sitting here, a nobody myself, spouting off in what could be considered a hypocritical tirade, guilty of the same thing Ms. Barr is. (现在，我完全意识到我正坐在这儿，只有我自己，进行着一次被认为是伪善的长篇演讲，对同巴尔遇到的同样的事儿感到内疚。)', 5, '2026-08-06 02:27:16', 'COCA词频', 17517);
INSERT INTO `word_bank` VALUES (98509, 'en', 'circumnavigate', '/sɜːkəm\'nævɪgeɪt/', '环航', 'v', 'For this year at least, our race to circumnavigate the globe in less than 80 days is over. (至少在今年，我们在八十天内完成环球航行结束了。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
