INSERT INTO `word_bank` VALUES (98526, 'en', 'excoriate', '/ɪk\'skɔːrɪeɪt; eks-/', '严厉的责难；擦破的皮肤', 'v', 'He proceeded to excoriate me in front of the nurses. (他继续在这些护士们面前指责我。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
