INSERT INTO `word_bank` VALUES (98529, 'en', 'drudgery', '/\'drʌdʒərɪ/', '苦工，苦差事', 'n', 'People want to get away from the drudgery of their everyday lives. (人们想摆脱日常生活中的苦差事。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
