INSERT INTO `word_bank` VALUES (98536, 'en', 'battalion', '/bəˈtæliən/', '（陆军的）一营（大约有一千兵士）; 大军，部队; （组织在一起工作的）队伍; 大批，许多，大量', 'n', 'Ten hours later Anthony was ordered to return to his battalion. (10小时之后安东尼被命令回营。)', 5, '2026-08-06 02:27:16', 'COCA词频', 8919);
