INSERT INTO `word_bank` VALUES (98559, 'en', 'coy', '/kɔɪ/', '腼腆的; 忸怩作态的; 献媚的', 'adj', 'She gave him a coy smile. (她对他含羞一笑。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17749);
INSERT INTO `word_bank` VALUES (98560, 'en', 'discretion', '/dɪˈskreʃn/', '慎重; 考虑周到; 判断力，辨别力; 自行决定的自由', 'n', 'British newspapers no longer feel they must treat the royal family with discretion. (英国报界不再觉得他们非得审慎对待王室不可了。)', 4, '2026-08-06 02:27:16', 'COCA词频', 7686);
INSERT INTO `word_bank` VALUES (98561, 'en', 'somnolent', '/\'sɒmnəl(ə)nt/', '催眠的，想睡的', 'adj', 'He lay quiet, somnolent after the day’s exertions. (他静静地躺着，劳累了一天之后感到十分困倦。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (98562, 'en', 'rapprochement', '/ræ\'prɒʃmɒ̃/', '友好，和睦; 〈外〉和解; 恢复邦交', 'n', 'Without settling this issue, Japan regards any form of rapprochement with North Korea as impossible. (在日本看来，不解决这个问题，就不可能与朝鲜恢复任何形式的友好关系。)', 3, '2026-08-06 02:27:16', 'COCA词频', 19982);
INSERT INTO `word_bank` VALUES (98563, 'en', 'compunction', '/kəm\'pʌŋkʃ(ə)n/', '悔恨，后悔；内疚', 'n', 'They used their tanks against the leftists without compunction . (他们肆无忌惮地使用坦克来对付左派人士。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
