INSERT INTO `word_bank` VALUES (98567, 'en', 'vehement', '/ˈvi:əmənt/', '激烈的，猛烈的；热烈的', 'adj', 'She suddenly became very vehement and agitated, jumping around and shouting. (她突然变得十分激动和不安，四处暴跳并大喊大叫。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
