INSERT INTO `word_bank` VALUES (98666, 'en', 'affluence', '/\'æflʊəns/', '富裕; 富足', 'n', 'The postwar era was one of new affluence for the working class. (战后时期是工人阶级新富期。)', 5, '2026-08-06 02:27:16', 'COCA词频', 15293);
