INSERT INTO `word_bank` VALUES (98671, 'en', 'repine', '/rɪ\'paɪn/', '抱怨；不满', 'v', 'This is the common fate of mortal men, useless it is to repine . (这是凡人的共同命运，抱怨也没有用。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
