INSERT INTO `word_bank` VALUES (98965, 'en', 'nadir', '/\'neɪdɪə; \'nædɪə/', '最低点，最底点；[天] 天底', 'n', 'By 1932, the depression had reached its nadir. (到1932年，经济大萧条到了最严重的程度。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (98966, 'en', 'foretell', '/fɔː\'tel/', '预言；预示；预告', 'v', 'the birth of Christ, foretold by prophets (先知们所预言的基督的诞生)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (98967, 'en', 'irate', '/aɪˈreɪt/', '盛怒的', 'adj', 'The owner was so irate he almost threw me out of the place. (主人那么生气，他差点儿把我从那个地方赶出去。)', 3, '2026-08-06 02:27:16', 'COCA词频', 17518);
