INSERT INTO `word_bank` VALUES (98980, 'en', 'assuage', '/əˈsweɪdʒ/', '减轻; 缓和; 平息; 使安静', 'vt', 'Nothing could assuage his guilt. (什么都不能减轻他的内疚。)', 5, '2026-08-06 02:27:16', 'COCA词频', 17438);
INSERT INTO `word_bank` VALUES (98981, 'en', 'recreant', '/\'rekrɪənt/', '懦夫；叛徒；胆小的；怯懦的；不忠的', 'n', 'I think I am a coward, a recreant and a fool. Even now I don\'t know how to react when he shows me his eyes and grin. (我觉得自己是个懦夫、叛徒、白痴。直到现在我也不知道要在他向我展示他的双眸和微笑时如何反应。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
