INSERT INTO `word_bank` VALUES (99001, 'en', 'commingle', '/kɒ\'mɪŋg(ə)l/', '使混合；掺和', 'v', 'Many towns allow recyclable items to be commingled for collection in a single container. (在许多城镇，可回收物品可以混放在一个容器里统一收走。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
