INSERT INTO `word_bank` VALUES (99062, 'en', 'brae', '/breɪ/', '斜坡；山坡', 'n', 'In participating in daily activity to make them can independent, be necessary to establish brae channel beside stair and elevatory floor, place auxiliary stand in proper place. (为让他们能独立参与到日常活动中，有必要在楼梯及升高的地板旁设斜坡通道，并在适当地点放置辅助支架。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
