INSERT INTO `word_bank` VALUES (99064, 'en', 'pertinacity', '/,pɜːtɪ\'næsɪtɪ/', '顽固；执拗', 'n', 'In the wide wide world there might be found another, his equal in pertinacity, but never in this little lane of ours. (在这个广袤的世界里，也许可以找到另外一个跟他一样执拗的人，但是在我们这个小巷子里根本不可能。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
