INSERT INTO `word_bank` VALUES (99072, 'en', 'venal', '/\'viːn(ə)l/', '贪污的；用金钱买得的；贿赂的；贪赃枉法的；(Venal)人名；(英)维纳尔', 'adj', 'our venal politicians (我们腐败的政客)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (99073, 'en', 'inalterable', '/ɪn\'ɔːlt(ə)rəb(ə)l; -\'ɒl-/', '不变的；不能变更的', 'adj', 'This is the cultural play of signification that theorists have discussed as if it were an inalterable feature of life. (这就是理论家们谈论的意义的文化游戏，仿佛它是生活的固定不变的特性。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (99074, 'en', 'concupiscence', '/kən\'kjuːpɪs(ə)ns/', '强烈的邪欲', 'n', 'Not in the lust of concupiscence, even as the Gentiles which know not God (不放纵私欲的邪情，像那不认识神的外邦人。)', 5, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (99075, 'en', 'commensurate', '/kəˈmenʃərət/', '（在时间和空间上）相等的; 相称的，相当的', 'adj', 'Employees are paid salaries commensurate with those of teachers. (发给雇员的薪水与发给教师的薪水相当。)', 4, '2026-08-06 02:27:16', 'COCA词频', 17387);
