INSERT INTO `word_bank` VALUES (99099, 'en', 'sinister', '/ˈsɪnɪstə(r)/', '危险的; 不吉祥的; 凶兆的; 险恶的', 'adj', 'There is a sinister side to these events. (这些事件有邪恶的一面。)', 4, '2026-08-06 02:27:16', 'COCA词频', 9803);
INSERT INTO `word_bank` VALUES (99100, 'en', 'dilatory', '/\'dɪlət(ə)rɪ/', '拖拉的；缓慢的，不慌不忙的', 'adj', 'You might expect politicians to smooth things out when civil servants are being dilatory. (当公务员办事拖拉时，你可能期望政治家们能够把事情顺利解决。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
