INSERT INTO `word_bank` VALUES (99103, 'en', 'behold', '/bɪˈhəʊld/', '看到，注视; 领悟', 'vt', 'She looked into his eyes and beheld madness. (透过他的眼睛，她看到了疯狂。)', 4, '2026-08-06 02:27:16', 'COCA词频', 10746);
INSERT INTO `word_bank` VALUES (99104, 'en', 'prerogative', '/prɪˈrɒgətɪv/', '特权，君权，天赋的特权（能力等）; 特性，特点，显著的优点', 'n', 'Arriving late is a woman’s prerogative . (迟到是女人的特权。)', 4, '2026-08-06 02:27:16', 'COCA词频', 12578);
INSERT INTO `word_bank` VALUES (99105, 'en', 'pipette', '/pɪ\'pet/', '移液管；吸移管；用移液器吸取', 'n', 'They are pushed to the sides of the dish where their tails are given a sharp smack with a pipette, to disable them. They are then ready to be injected into an egg. (然后把它们头部推送到培养皿的另一侧，尾部则暴露在移液枪尖尖的吸管下，最后把它们注射到卵子中去。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (99106, 'en', 'celibate', '/ˈselɪbət/', '独身者', 'n', '...the U.S.A.\'s biggest group of celibates. (…美国最大的独身宗教群体。)', 4, '2026-08-06 02:27:16', 'COCA词频', 18525);
INSERT INTO `word_bank` VALUES (99107, 'en', 'brevity', '/\'brevɪtɪ/', '简洁，简短；短暂，短促', 'n', 'Letters published in the newspaper are edited for brevity and clarity. (报上刊登的来信都要编辑得简洁明了。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (99108, 'en', 'culmination', '/ˌkʌlmɪˈneɪʃn/', '顶点，极点; 高潮; 极盛期; 完成，成就', 'n', 'This little book represented the culmination of 15 years’ work. (这本小书是15年工作的结晶。)', 4, '2026-08-06 02:27:16', 'COCA词频', 13181);
INSERT INTO `word_bank` VALUES (99109, 'en', 'malignancy', '/məˈlɪgnənsi/', '恶意', 'n', 'Tissue that is removed during the operation is checked for signs of malignancy. (手术过程中切除的组织用于诊断疾病是否为恶性。)', 4, '2026-08-06 02:27:16', 'COCA词频', 19690);
INSERT INTO `word_bank` VALUES (99110, 'en', 'habitude', '/\'hæbɪtjuːd/', '习俗；习惯', 'n', 'From long time ago, Chinese and Russia has become a kind of unique culture in tea history, tea habitude, tea sets and poems for tea. (千百年来，中华民族和俄罗斯民族在饮茶的历史、饮茶习俗、茶具等方面，都形成了独具特色的茶文化。)', 4, '2026-08-06 02:27:16', 'SAT', NULL);
INSERT INTO `word_bank` VALUES (99111, 'en', 'circumlocution', '/,sɜːkəmlə\'kjuːʃ(ə)n/', '婉转曲折的说法，累赘的陈述；遁辞', 'n', NULL, 5, '2026-08-06 02:27:16', 'SAT', NULL);
