INSERT INTO `word_bank` VALUES (99124, 'en', 'inveigh', '/ɪn\'veɪ/', '痛骂；漫骂；猛烈抨击', 'v', 'A lot of his writings inveigh against luxury and riches. (他的许多作品猛烈抨击了奢侈和富有。)', 3, '2026-08-06 02:27:16', 'SAT', NULL);
