INSERT INTO `word_bank` VALUES (174733, 'en', 'lithospheric', NULL, '岩石圈的; 陆界的', 'adj', 'A mid-ocean ridge is a boundary between plates where new lithospheric material is injected from below. (一道中海脊是板块之间的边界，在那里新的岩石圈的物质从下部注入。)', 4, '2026-08-06 02:32:09', '托福', NULL);
