INSERT INTO `word_bank` VALUES (175735, 'en', 'domelike', NULL, '穹顶状的', 'adj', 'A domelike gunner\'s enclosure projecting from the fuselage of a combat aircraft. (战斗机上圆顶形的封闭式结构，炮手的位置，从飞机机身上突出。)', 4, '2026-08-06 02:32:09', '托福', NULL);
