INSERT INTO `word_bank` VALUES (176735, 'en', 'useless', '/ˈju:sləs/', '无用的，无效的; 无价值的; 差劲的; 不怎么样的', 'adj', 'The editor killed a few useless lines. (编辑删掉了几行无用的文字。)', 4, '2026-08-06 02:32:09', 'COCA词频', 5738);
INSERT INTO `word_bank` VALUES (176736, 'en', 'lateness', NULL, '迟, 晚', 'n', 'I must report your lateness to the teacher. (我必须报告老师你迟到了。)', 4, '2026-08-06 02:32:09', '托福', NULL);
