INSERT INTO `word_bank` VALUES (178771, 'en', 'industrially', NULL, '企业[工业]地', 'adv', 'He added: “You can imagine a situation when some of our industrially important but polluting processes are done in space and the finished products are brought back down to Earth. (他补充说：“你可以想象一种情况，当我们的一些工业污染的过程是重要的，但做的空间和成品带回了地球。)', 3, '2026-08-06 02:32:09', '托福', NULL);
INSERT INTO `word_bank` VALUES (178772, 'en', 'restatement', NULL, '再声明, 重述', 'n', 'I hope this book is not yet another restatement of the prevailing wisdom. (我希望这本书不会又是重复一些流行的至理名言。)', 4, '2026-08-06 02:32:09', '托福', NULL);
