INSERT INTO `word_bank` VALUES (178794, 'en', 'threadlike', NULL, '线状的', 'adj', 'Genes are spiraled, threadlike particles made of DNA (deoxyribonucleic acid). (基因是由DNA（脱氧核糖核酸）组成的丝状螺旋微粒。)', 4, '2026-08-06 02:32:09', '托福', NULL);
