INSERT INTO `word_bank` VALUES (178796, 'en', 'survivability', NULL, '残存性', 'n', 'It is an important improvement in the survivability of the crew while maintaining the dynamics and payload of the aircrafts. (这对同时保持飞机的动力、负重以及生存性上是一个重要的提升。)', 3, '2026-08-06 02:32:09', '托福', NULL);
