INSERT INTO `word_bank` VALUES (178798, 'en', 'unsureness', NULL, '不确定, 缺乏自信', 'n', 'The public psychosocial status is mostly affected by the unsureness of information in the event of epidemic outbreak. (面对疫情及突发事件，信息的不确定性是影响民众心态变化的主要因素。)', 3, '2026-08-06 02:32:09', '托福', NULL);
INSERT INTO `word_bank` VALUES (179232, 'en', 'hohokam', NULL, '霍霍坎文化的', 'adj', 'The hohokam culture disintegrated as they had difficulty maintaining the canals in the dry conditions of the drought. (当干旱的条件使得运河很难被维护好的时候，霍霍坎文化瓦解了。)', 4, '2026-08-06 02:32:09', '托福', NULL);
