INSERT INTO `word_bank` VALUES (179247, 'en', 'noisily', '/\'nɔɪzɪlɪ/', '吵闹地; 喧喧嚷嚷', 'adv', 'It’s a colorful scene - laborers unload noisily, and small groups of women haggle for the pots of crabs and sardines to sell at village markets. (在这个热闹的环境中，工人喧闹地卸着船，三五成群的妇女正在为一盆盆螃蟹和沙丁鱼讨价还价，以便在村里的鱼市出售。)', 3, '2026-08-06 02:32:09', 'COCA词频', 16836);
