INSERT INTO `word_bank` VALUES (179737, 'en', 'vaguest', NULL, '含糊的，不明确的', 'adj', 'Describe project deliverables in the vaguest possible terms so sponsors and reviewers have plenty of leeway to reinvent the project outputs repeatedly as the project unfolds. (用尽可能模糊的语言描述项目可交付成果，让发起人及审核者随着项目的开展，能有足够的空间不断地重新定义项目成果。)', 4, '2026-08-06 02:32:09', '托福', NULL);
