INSERT INTO `word_bank` VALUES (179752, 'en', 'attractively', NULL, '有吸引力地，诱人地', 'adv', 'In terms of valuation, the run of strong earnings combined with declining stock prices translate into some attractively priced stocks. (在估值方面，强劲的盈利走势加上下跌的股价，其结果就是价格具有吸引力的股票。)', 4, '2026-08-06 02:32:09', '托福', NULL);
INSERT INTO `word_bank` VALUES (179753, 'en', 'modus', NULL, '方法, 形式', 'n', 'The problem is, I do not have any technique, process, or modus operandi. (问题是，我不知道任何技巧、步骤或操作方式。)', 4, '2026-08-06 02:32:09', '托福', NULL);
INSERT INTO `word_bank` VALUES (179754, 'en', 'laborsaving', NULL, '节省劳力的;省力气的', 'adj', 'The way to make self-sufficiency work on a small scale is to resist the temptation to buy a tractor and other expensive laborsaving devices. (小范围里实现自给自足的途径是抵制诱惑，不去购置拖拉机和其他昂贵的节省劳力的机械。)', 5, '2026-08-06 02:32:09', '托福', NULL);
