INSERT INTO `word_bank` VALUES (179756, 'en', 'wingless', NULL, '无翼的, 没有翅膀的', 'adj', 'It is a parable. We are the wingless birds, and our duties and tasks are the pinions God has made to lift us up and carry us heavenward. (读者，这是一个比喻，我们就是那些无翅的小鸟，我们的工作和职务是神替我们预备带领我们向天的翅翼。)', 3, '2026-08-06 02:32:09', '托福', NULL);
INSERT INTO `word_bank` VALUES (179757, 'en', 'multifunctional', NULL, '多功能的', 'adj', 'This hormone is multifunctional, but one of its main tasks is to act as a neurotransmitter and regulate serotonin levels. (这种激素是多功能的，但它的主要功能是作为神经递质并调节血清素含量。)', 5, '2026-08-06 02:32:09', '托福', NULL);
