INSERT INTO `word_bank` VALUES (179762, 'en', 'insensitivity', NULL, '感觉迟钝,不灵敏性', 'n', 'But its insensitivity means the shift is almost too small to measure and complicated to calculate. (但它的不敏感性意味着偏移小到几乎无法测量和计算复杂到无法计算。)', 4, '2026-08-06 02:32:09', '托福', NULL);
