DROP TABLE IF EXISTS `error_book`;
CREATE TABLE `error_book`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `word_id` bigint NOT NULL,
  `error_count` int NOT NULL DEFAULT 1 COMMENT '累计错误次数',
  `last_error_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `next_review_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下次复习时间',
  `mastered` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已掌握',
  `easiness_factor` double NULL DEFAULT 2.5 COMMENT '难易度因子',
  `review_interval` int NULL DEFAULT 0 COMMENT '复习间隔天',
  `repetitions` int NULL DEFAULT 0 COMMENT '连续答对次数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_word`(`user_id` ASC, `word_id` ASC) USING BTREE,
  INDEX `idx_user_review`(`user_id` ASC, `mastered` ASC, `next_review_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 68 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '错题本' ROW_FORMAT = Dynamic;

