DROP TABLE IF EXISTS `word_bank`;
CREATE TABLE `word_bank`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `language` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '语言代码: en/ja/de/fr/ko',
  `word` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '单词或短语',
