  `part_of_speech` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '词性',
  `example` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '例句',
  `difficulty` tinyint NOT NULL DEFAULT 1 COMMENT '难度 1-5',
